let idpEntries = []; // {id, name, projectName, rows, count, error}
let idpEntrySeq = 0;
let idpLastData = null;

idpDrop.addEventListener('click', ()=> idpFile.click());
idpDrop.addEventListener('dragover', e=>{ e.preventDefault(); idpDrop.classList.add('drag'); });
idpDrop.addEventListener('dragleave', ()=> idpDrop.classList.remove('drag'));
