// Populate the month-range selects once; default to Junho–Novembro, the
// semester window used in the original spreadsheet ("Total Semestre").
(function initIdpMonthSelects(){
  const startSel = document.getElementById('idpMonthStart');
  const endSel = document.getElementById('idpMonthEnd');
  startSel.innerHTML = MONTH_PT.map((m,i)=>`<option value="${i}">${m}</option>`).join('');
  endSel.innerHTML = MONTH_PT.map((m,i)=>`<option value="${i}">${m}</option>`).join('');
  startSel.value = 5;  // Junho
  endSel.value = 10;   // Novembro
})();

async function handleIdpFiles(files){
  idpError.innerHTML = '';
  for(const file of files){
    const entry = {id: ++idpEntrySeq, name: file.name, projectName: deriveProjectNameFromFile(file.name), rows:null, count:0, error:null};
    idpEntries.push(entry);
    idpProgress.innerHTML = `<div class="progress-item"><span class="spinner"></span> Lendo ${file.name}…</div>`;
    await new Promise(r=>setTimeout(r,0));
    try{
      const matrix = await readWorkbookMatrix(file);
      const rows = parseWithHeaderDetection(matrix, REQUIRED_IDP_COLS);
      if(!rows){
        entry.error = 'Não encontrei o cabeçalho (Ano, Mês, Disciplina tarefa, Custo da Linha de Base, Custo Real).';
      } else {
        entry.rows = rows;
        entry.count = rows.length;
      }
    }catch(err){
      entry.error = err.message;
    }
    renderIdpFileList();
    await new Promise(r=>setTimeout(r,0));
  }
  idpProgress.innerHTML = '';
  combineAndRenderIdp();
}

function renderIdpFileList(){
  if(!idpEntries.length){ idpFileList.innerHTML=''; return; }
  idpFileList.innerHTML = `<div class="file-list">${idpEntries.map(e=>{
    if(e.error) return `<span class="file-pill error">${e.name} · erro: ${e.error} <button onclick="removeIdpEntry(${e.id})">✕</button></span>`;
    if(!e.rows) return `<span class="file-pill">${e.name} · lendo… <button onclick="removeIdpEntry(${e.id})">✕</button></span>`;
    return `<span class="file-pill">
      <input class="proj-name" value="${e.projectName}" onchange="renameIdpEntry(${e.id}, this.value)">
      · ${e.count.toLocaleString('pt-BR')} linhas
      <button onclick="removeIdpEntry(${e.id})">✕</button>
    </span>`;
  }).join('')}</div>`;
}

function renameIdpEntry(id, newName){
  const e = idpEntries.find(x=>x.id===id);
  if(e){ e.projectName = newName.trim() || e.projectName; combineAndRenderIdp(); }
}
function removeIdpEntry(id){
  idpEntries = idpEntries.filter(e=>e.id!==id);
  renderIdpFileList();
  if(idpEntries.some(e=>e.rows)) combineAndRenderIdp();
  else { idpResults.style.display='none'; }
}

function combineAndRenderIdp(){
  const combined = [];
  idpEntries.forEach(e=>{
    if(!e.rows) return;
    e.rows.forEach(r=>{
      const ano = String(r['ano']||'').trim();
      const mes = String(r['mês']||'').trim();
      const disc = String(r['disciplina_tarefa']||'').trim();
      const lb = parseFloat(r['custo_da_linha_de_base']) || 0;
      const real = parseFloat(r['custo_real']) || 0;
      if(!ano || ano.toLowerCase()==='total geral') return;
      if(!disc || disc.toUpperCase()==='NULL') return; // subtotal rows, not a tagged discipline
      const mi = monthIndexPt(mes);
      if(mi === -1) return;
      combined.push({ unit: e.projectName, ano, mes, mi, disc, lb, real });
    });
  });

  if(!combined.length){ idpResults.style.display='none'; return; }

  // Year selector — default to 2026 (the semester this tool tracks) when present,
  // otherwise fall back to whichever year has the most real-cost activity
  // (future years often only carry baseline/budget entries with zero actual cost yet).
  const years = Array.from(new Set(combined.map(r=>r.ano))).sort();
  const realByYear = new Map();
  combined.forEach(r=>{ realByYear.set(r.ano, (realByYear.get(r.ano)||0) + r.real); });
  let defaultYear = years.includes('2026') ? '2026' : years[years.length-1];
  if(!years.includes('2026')){
    let bestReal = -1;
    years.forEach(y=>{
      const v = realByYear.get(y) || 0;
      if(v > bestReal){ bestReal = v; defaultYear = y; }
    });
  }

  const yearSel = document.getElementById('idpYear');
  const prevYear = yearSel.value;
  yearSel.innerHTML = years.map(y=>`<option value="${y}">${y}</option>`).join('');
  yearSel.value = years.includes(prevYear) ? prevYear : defaultYear;
  const selectedYear = yearSel.value;

  let monthStart = parseInt(document.getElementById('idpMonthStart').value);
  let monthEnd = parseInt(document.getElementById('idpMonthEnd').value);
  if(monthEnd < monthStart){ [monthStart, monthEnd] = [monthEnd, monthStart]; }

  const rows = combined.filter(r=> r.ano === selectedYear && r.mi >= monthStart && r.mi <= monthEnd);

  idpResults.style.display = 'block';
  if(!rows.length){
    document.getElementById('idpCards').innerHTML = `<div class="card"><div class="lbl">Sem dados</div><div class="sub">Nenhum lançamento entre ${MONTH_PT[monthStart]} e ${MONTH_PT[monthEnd]} de ${selectedYear}</div></div>`;
    document.getElementById('idpUnitTable').innerHTML = '';
    document.getElementById('idpDisciplineTable').innerHTML = '';
    document.getElementById('idpUnitDetailTable').innerHTML = '';
    return;
  }

  // Meta = minimum adherence to hit full points, matching the "2026" scorecard logic
  // (BD column: IF(result >= meta, full points, 0)) — not a symmetric tolerance band.
  const tolerance = (parseFloat(document.getElementById('idpTolerance').value) || 98) / 100;

  // By unit
  const byUnit = new Map();
  rows.forEach(r=>{
    if(!byUnit.has(r.unit)) byUnit.set(r.unit, {lb:0, real:0});
    const u = byUnit.get(r.unit); u.lb += r.lb; u.real += r.real;
  });

  // By discipline (consolidated)
  const byDisc = new Map();
  rows.forEach(r=>{
    if(!byDisc.has(r.disc)) byDisc.set(r.disc, {lb:0, real:0});
    const d = byDisc.get(r.disc); d.lb += r.lb; d.real += r.real;
  });

  // By unit -> discipline -> month
  const byUnitDetail = new Map();
  rows.forEach(r=>{
    if(!byUnitDetail.has(r.unit)) byUnitDetail.set(r.unit, new Map());
    const discMap = byUnitDetail.get(r.unit);
    if(!discMap.has(r.disc)) discMap.set(r.disc, new Map());
    const monthMap = discMap.get(r.disc);
    const key = r.mi; // 0-11
    if(!monthMap.has(key)) monthMap.set(key, {lb:0, real:0});
    const mm = monthMap.get(key); mm.lb += r.lb; mm.real += r.real;
  });

  // Totals
  let totalLb=0, totalReal=0;
  byUnit.forEach(u=>{ totalLb += u.lb; totalReal += u.real; });
  const aderGeral = totalLb ? totalReal/totalLb : 0;

  // Grouped discipline cards: Civil (01), Mecânica (02), EIA = Elétrica+Instrumentação+Automação (04+05+06)
  function sumDisciplineCodes(codes){
    let lb=0, real=0;
    byDisc.forEach((d,name)=>{ if(codes.includes(disciplineSortKey(name))){ lb+=d.lb; real+=d.real; } });
    return { lb, real, ad: lb ? real/lb : 0 };
  }
  const civilAgg = sumDisciplineCodes([1]);
  const mecanicaAgg = sumDisciplineCodes([2]);
  const eiaAgg = sumDisciplineCodes([4,5,6]);

  function disciplineCardHtml(lbl, agg){
    const ok = agg.ad >= tolerance;
    return `<div class="card">
      <div class="lbl">${lbl}</div>
      <div class="val" style="font-size:20px;">${fmtPct(agg.ad)}</div>
      <div class="sub"><span class="badge ${ok?'ok':'fail'}">${agg.lb? (ok?'Dentro da meta':'Fora da meta') : 'Sem dados'}</span></div>
    </div>`;
  }

  document.getElementById('idpCards').innerHTML = `
    <div class="card"><div class="lbl">Custo Linha de Base</div><div class="val" style="font-size:20px;">${fmtCurrency(totalLb)}</div></div>
    <div class="card"><div class="lbl">Custo Real</div><div class="val" style="font-size:20px;">${fmtCurrency(totalReal)}</div></div>
    <div class="card accent"><div class="lbl">Aderência geral</div><div class="val">${fmtPct(aderGeral)}</div></div>
    <div class="card"><div class="lbl">Unidades carregadas</div><div class="val">${byUnit.size}</div></div>
    ${disciplineCardHtml('Civil', civilAgg)}
    ${disciplineCardHtml('Mecânica', mecanicaAgg)}
    ${disciplineCardHtml('EIA', eiaAgg)}
  `;

  // Unit table
  const unitRows = Array.from(byUnit.entries()).sort((a,b)=> b[1].real - a[1].real);
  document.getElementById('idpUnitTable').innerHTML = `
    <thead><tr><th>Unidade</th><th>Custo Linha de Base</th><th>Custo Real</th><th>Aderência</th><th>Situação</th></tr></thead>
    <tbody>${unitRows.map(([name,d])=>{
      const ad = d.lb ? d.real/d.lb : 0;
      const ok = ad >= tolerance;
      return `<tr>
        <td>${name}</td><td class="num">${fmtCurrency(d.lb)}</td><td class="num">${fmtCurrency(d.real)}</td>
        <td class="num">${fmtPct(ad)}</td><td><span class="badge ${ok?'ok':'fail'}">${ok?'Dentro da meta':'Fora da meta'}</span></td>
      </tr>`;
    }).join('') || '<tr><td colspan="5">Sem dados</td></tr>'}</tbody>
  `;

  // Discipline table
  const discRows = Array.from(byDisc.entries()).sort((a,b)=> disciplineSortKey(a[0])-disciplineSortKey(b[0]));
  document.getElementById('idpDisciplineTable').innerHTML = `
    <thead><tr><th>Disciplina</th><th>Custo Linha de Base</th><th>Custo Real</th><th>Aderência</th><th>Situação</th></tr></thead>
    <tbody>${discRows.map(([name,d])=>{
      const ad = d.lb ? d.real/d.lb : 0;
      const ok = ad >= tolerance;
      return `<tr>
        <td>${name}</td><td class="num">${fmtCurrency(d.lb)}</td><td class="num">${fmtCurrency(d.real)}</td>
        <td class="num">${fmtPct(ad)}</td><td><span class="badge ${ok?'ok':'fail'}">${ok?'Dentro da meta':'Fora da meta'}</span></td>
      </tr>`;
    }).join('') || '<tr><td colspan="5">Sem dados</td></tr>'}</tbody>
  `;

  // Unit detail select
  const unitDetailSelect = document.getElementById('idpUnitDetailSelect');
  const prevSel = unitDetailSelect.value;
  const unitNames = Array.from(byUnitDetail.keys());
  unitDetailSelect.innerHTML = unitNames.map(u=>`<option value="${u}">${u}</option>`).join('');
  unitDetailSelect.value = unitNames.includes(prevSel) ? prevSel : unitNames[0];

  idpLastData = { selectedYear, monthStart, monthEnd, tolerance, totalLb, totalReal, aderGeral, unitRows, discRows, byUnitDetail, civilAgg, mecanicaAgg, eiaAgg };
  renderIdpUnitDetail();
}

function renderIdpUnitDetail(){
  if(!idpLastData) return;
  const unit = document.getElementById('idpUnitDetailSelect').value;
  const discMap = idpLastData.byUnitDetail.get(unit);
  const table = document.getElementById('idpUnitDetailTable');
  if(!discMap){ table.innerHTML=''; return; }

  // collect months present across this unit's disciplines, chronological
  const monthsPresent = new Set();
  discMap.forEach(monthMap=> monthMap.forEach((v,mi)=> monthsPresent.add(mi)));
  const months = Array.from(monthsPresent).sort((a,b)=>a-b);

  const discEntries = Array.from(discMap.entries()).sort((a,b)=> disciplineSortKey(a[0])-disciplineSortKey(b[0]));

  const headCols = months.map(mi=>`<th colspan="3">${MONTH_PT[mi]}</th>`).join('') + '<th colspan="3">Total do período</th>';
  const subCols = months.map(()=>'<th>LB</th><th>Real</th><th>Ader.</th>').join('') + '<th>LB</th><th>Real</th><th>Ader.</th>';

  const bodyRows = discEntries.map(([disc, monthMap])=>{
    let totLb=0, totReal=0;
    const cells = months.map(mi=>{
      const d = monthMap.get(mi) || {lb:0, real:0};
      totLb += d.lb; totReal += d.real;
      const ad = d.lb ? d.real/d.lb : 0;
      return `<td class="num">${fmtCurrency(d.lb)}</td><td class="num">${fmtCurrency(d.real)}</td><td class="num">${fmtPct(ad)}</td>`;
    }).join('');
    const totAd = totLb ? totReal/totLb : 0;
    return `<tr><td>${disc}</td>${cells}<td class="num">${fmtCurrency(totLb)}</td><td class="num">${fmtCurrency(totReal)}</td><td class="num">${fmtPct(totAd)}</td></tr>`;
  }).join('');

  table.innerHTML = `
    <thead>
      <tr><th rowspan="2">Disciplina</th>${headCols}</tr>
      <tr>${subCols}</tr>
    </thead>
    <tbody>${bodyRows || '<tr><td>Sem dados</td></tr>'}</tbody>
  `;
}

document.getElementById('idpExportPdf').addEventListener('click', ()=>{
  if(!idpLastData) return;
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit:'pt', format:'a4' });
  const d = idpLastData;
  const today = new Date().toLocaleDateString('pt-BR');

  doc.setFont('helvetica','bold'); doc.setFontSize(16); doc.setTextColor(48,79,126);
  doc.text('IDP - Disciplinas', 40, 44);
  doc.setFont('helvetica','normal'); doc.setFontSize(9); doc.setTextColor(110,110,110);
  doc.text(`Gerado em ${today} · período: ${MONTH_PT[d.monthStart]} a ${MONTH_PT[d.monthEnd]}/${d.selectedYear} · meta de aderência: ${(d.tolerance*100).toFixed(0)}%`, 40, 60);

  const cardData = [
    { lbl:'CUSTO LINHA DE BASE', val: fmtCurrency(d.totalLb), accent:false },
    { lbl:'CUSTO REAL', val: fmtCurrency(d.totalReal), accent:false },
    { lbl:'ADERÊNCIA GERAL', val: fmtPct(d.aderGeral), accent:true },
  ];
  const cardY=78, cardH=48, gap=12, marginX=40;
  const cardW = (515-gap*2)/3;
  cardData.forEach((c,i)=>{
    const x = marginX + i*(cardW+gap);
    doc.setDrawColor(228,230,234); doc.setFillColor(255,255,255);
    doc.roundedRect(x, cardY, cardW, cardH, 5, 5, 'FD');
    doc.setFont('helvetica','bold'); doc.setFontSize(7.5); doc.setTextColor(107,114,128);
    doc.text(c.lbl, x+10, cardY+17);
    doc.setFont('helvetica','bold'); doc.setFontSize(14);
    doc.setTextColor(...(c.accent?[234,162,57]:[33,55,88]));
    doc.text(c.val, x+10, cardY+35);
  });

  const cardY2 = cardY + cardH + 12;
  const cardData2 = [
    { lbl:'CIVIL', val: fmtPct(d.civilAgg.ad) },
    { lbl:'MECÂNICA', val: fmtPct(d.mecanicaAgg.ad) },
    { lbl:'EIA', val: fmtPct(d.eiaAgg.ad) },
  ];
  cardData2.forEach((c,i)=>{
    const x = marginX + i*(cardW+gap);
    doc.setDrawColor(228,230,234); doc.setFillColor(255,255,255);
    doc.roundedRect(x, cardY2, cardW, cardH, 5, 5, 'FD');
    doc.setFont('helvetica','bold'); doc.setFontSize(7.5); doc.setTextColor(107,114,128);
    doc.text(c.lbl, x+10, cardY2+17);
    doc.setFont('helvetica','bold'); doc.setFontSize(14); doc.setTextColor(33,55,88);
    doc.text(c.val, x+10, cardY2+35);
  });

  doc.autoTable({
    startY: cardY2+cardH+20,
    head: [['Unidade','Linha de Base','Real','Aderência','Situação']],
    body: d.unitRows.map(([name,dd])=>{
      const ad = dd.lb? dd.real/dd.lb:0;
      const ok = ad>=d.tolerance;
      return [name, fmtCurrency(dd.lb), fmtCurrency(dd.real), fmtPct(ad), ok?'Dentro da meta':'Fora da meta'];
    }),
    headStyles:{fillColor:[48,79,126],textColor:255,fontStyle:'bold'},
    styles:{font:'helvetica',fontSize:9,cellPadding:5}, theme:'grid',
    didParseCell:(data)=>{ if(data.section==='body'&&data.column.index===4){ data.cell.styles.textColor = data.cell.raw==='Dentro da meta'?[96,147,70]:[192,57,43]; data.cell.styles.fontStyle='bold'; } }
  });

  const y2 = doc.lastAutoTable.finalY + 24;
  doc.setFont('helvetica','bold'); doc.setFontSize(12); doc.setTextColor(48,79,126);
  doc.text('Aderência por disciplina', 40, y2);
  doc.autoTable({
    startY: y2+10,
    head: [['Disciplina','Linha de Base','Real','Aderência','Situação']],
    body: d.discRows.map(([name,dd])=>{
      const ad = dd.lb? dd.real/dd.lb:0;
      const ok = ad>=d.tolerance;
      return [name, fmtCurrency(dd.lb), fmtCurrency(dd.real), fmtPct(ad), ok?'Dentro da meta':'Fora da meta'];
    }),
    headStyles:{fillColor:[48,79,126],textColor:255,fontStyle:'bold'},
    styles:{font:'helvetica',fontSize:9,cellPadding:5}, theme:'grid',
    didParseCell:(data)=>{ if(data.section==='body'&&data.column.index===4){ data.cell.styles.textColor = data.cell.raw==='Dentro da meta'?[96,147,70]:[192,57,43]; data.cell.styles.fontStyle='bold'; } }
  });

  doc.save(`IDP_Disciplinas_${d.selectedYear}_${MONTH_PT[d.monthStart]}-${MONTH_PT[d.monthEnd]}_${new Date().toISOString().slice(0,10)}.pdf`);
});

/* ---------- IDC - Custos tab (Forecast side) ---------- */

// Scans every sheet of a workbook looking for a column whose values include
// "Orçado" / "Real+FCST" tags, next to a row of month/date headers. Different
// files use different sheet names and column positions, so this is generic.
function detectOrcadoRealSheet(workbook){
  let best = null;
  workbook.SheetNames.forEach(sheetName=>{
    const sheet = workbook.Sheets[sheetName];
    let matrix = XLSX.utils.sheet_to_json(sheet, {header:1, defval:null, raw:true});
    // Some workbooks report huge phantom dimensions (1M+ rows) even though the
    // real data is a few hundred rows — cap it so parsing stays fast and safe.
    if(matrix.length > 5000) matrix = matrix.slice(0, 5000);
    const scanRows = Math.min(matrix.length, 40);

    // find a row that looks like a month-header row: a run of >=4 Date objects (or date-like)
    let headerRowIdx = -1, monthCols = [];
    for(let r=0; r<scanRows; r++){
      const row = matrix[r] || [];
      const cols = [];
      row.forEach((v,ci)=>{ if(v instanceof Date && !isNaN(v)) cols.push(ci); });
      if(cols.length >= 4){ headerRowIdx = r; monthCols = cols; break; }
    }
    if(headerRowIdx === -1) return;

    // find the tag column: any column where, scanning rows below the header,
    // a good fraction of non-null values start with "orçado"/"orcado" or "real+fcst"
    let tagCol = -1, bestScore = 0;
    let maxCol = 0;
    matrix.forEach(r=>{ if(r && r.length>maxCol) maxCol = r.length; });
    for(let c=0; c<maxCol; c++){
      let orc=0, real=0, total=0;
      for(let r=headerRowIdx+1; r<matrix.length; r++){
        const v = matrix[r] ? matrix[r][c] : null;
        if(v===null || v==='') continue;
        const s = String(v).trim().toLowerCase();
        if(s.startsWith('orçado') || s.startsWith('orcado')){ orc++; total++; }
        else if(s.startsWith('real+fcst') || s.startsWith('real + fcst') || s.startsWith('real +fcst')){ real++; total++; }
      }
      if(orc>3 && real>3 && total>bestScore){ bestScore = total; tagCol = c; }
    }
    if(tagCol === -1) return;

    if(!best || bestScore > best.score){
      best = { sheetName, matrix, headerRowIdx, monthCols, tagCol, score: bestScore };
    }
  });
  return best;
}

function toNumberOrZero(v){
  if(v===null || v===undefined) return 0;
  if(typeof v==='number') return isNaN(v) ? 0 : v;
  const s = String(v).trim();
  if(s==='' || s==='-') return 0;
  const n = parseFloat(s.replace(/\./g,'').replace(',', '.'));
  return isNaN(n) ? 0 : n;
}

function guessScale(monthlyTotalsSum){
  // Heuristic: real construction budgets run into the tens/hundreds of millions.
  // If the raw monthly sum is implausibly small, the sheet is very likely in R$ millions.
  return monthlyTotalsSum > 0 && monthlyTotalsSum < 50000 ? 1000000 : 1;
}

const idcFcstDrop = document.getElementById('idcFcstDrop');
const idcFcstFile = document.getElementById('idcFcstFile');
const idcFcstFileList = document.getElementById('idcFcstFileList');
const idcFcstProgress = document.getElementById('idcFcstProgress');
const idcFcstError = document.getElementById('idcFcstError');
const idcFcstResults = document.getElementById('idcFcstResults');

let idcFcstEntries = []; // {id, name, projectName, scale, monthly:{previsto:Map(dateKey->val), realFcst:Map}, sheetUsed, error}
let idcFcstEntrySeq = 0;

idcFcstDrop.addEventListener('click', ()=> idcFcstFile.click());
idcFcstDrop.addEventListener('dragover', e=>{ e.preventDefault(); idcFcstDrop.classList.add('drag'); });
idcFcstDrop.addEventListener('dragleave', ()=> idcFcstDrop.classList.remove('drag'));
idcFcstDrop.addEventListener('drop', e=>{
  e.preventDefault(); idcFcstDrop.classList.remove('drag');
  if(e.dataTransfer.files.length) handleIdcFcstFiles(Array.from(e.dataTransfer.files));
});
idcFcstFile.addEventListener('change', e=>{
  if(e.target.files.length) handleIdcFcstFiles(Array.from(e.target.files));
  idcFcstFile.value = '';
});

async function handleIdcFcstFiles(files){
  idcFcstError.innerHTML = '';
  for(const file of files){
    const guessed = guessMonthYearFromFilename(file.name);
    const entry = { id: ++idcFcstEntrySeq, name: file.name, projectName: deriveProjectNameFromFile(file.name), scale:1, monthly:null, sheetUsed:null, error:null, refMonth: guessed.month, refYear: guessed.year };
    idcFcstEntries.push(entry);
    idcFcstProgress.innerHTML = `<div class="progress-item"><span class="spinner"></span> Lendo ${file.name}…</div>`;
    await new Promise(r=>setTimeout(r,0));
    try{
      const buf = await file.arrayBuffer();
      const wb = XLSX.read(buf, {type:'array', cellDates:true});
      const detected = detectOrcadoRealSheet(wb);
      if(!detected){
        entry.error = 'Não encontrei uma aba com colunas "Orçado" / "Real+FCST" e cabeçalho de meses.';
      } else {
        const { matrix, headerRowIdx, monthCols, tagCol, sheetName } = detected;
        const previsto = new Map(); // 'YYYY-MM' -> sum
        const realFcst = new Map();
        let rawSum = 0;
        for(let r=headerRowIdx+1; r<matrix.length; r++){
          const row = matrix[r]; if(!row) continue;
          const tagRaw = row[tagCol];
          if(tagRaw===null || tagRaw==='') continue;
          const tag = String(tagRaw).trim().toLowerCase();
          let target = null;
          if(tag.startsWith('orçado') || tag.startsWith('orcado')) target = previsto;
          else if(tag.startsWith('real+fcst') || tag.startsWith('real + fcst') || tag.startsWith('real +fcst')) target = realFcst;
          if(!target) continue;
          monthCols.forEach(ci=>{
            const dateVal = matrix[headerRowIdx][ci];
            const key = dateVal.getFullYear()+'-'+String(dateVal.getMonth()+1).padStart(2,'0');
            const val = toNumberOrZero(row[ci]);
            target.set(key, (target.get(key)||0) + val);
            rawSum += Math.abs(val);
          });
        }
        entry.scale = guessScale(rawSum);
        entry.monthly = { previsto, realFcst };
        entry.sheetUsed = sheetName;
      }
    }catch(err){
      entry.error = err.message;
    }
    renderIdcFcstFileList();
    await new Promise(r=>setTimeout(r,0));
  }
  idcFcstProgress.innerHTML = '';
  renderIdcFcstPreview();
}

function guessMonthYearFromFilename(filename){
  const norm = filename.toUpperCase();
  const yearMatch = norm.match(/20\d{2}/);
  const year = yearMatch ? parseInt(yearMatch[0]) : new Date().getFullYear();
  for(let i=0;i<MONTH_PT.length;i++){
    if(norm.includes(MONTH_PT[i].toUpperCase())) return { month: i, year };
  }
  return { month: null, year };
}

let idcFcstActiveMonth = 'all'; // 'all' or 'M-YYYY' key

function renderIdcFcstFileList(){
  if(!idcFcstEntries.length){ idcFcstFileList.innerHTML=''; return; }
  idcFcstFileList.innerHTML = `<div class="file-list">${idcFcstEntries.map(e=>{
    if(e.error) return `<span class="file-pill error">${e.name} · erro: ${e.error} <button onclick="removeIdcFcstEntry(${e.id})">✕</button></span>`;
    if(!e.monthly) return `<span class="file-pill">${e.name} · lendo… <button onclick="removeIdcFcstEntry(${e.id})">✕</button></span>`;
    const monthOptions = MONTH_PT.map((m,i)=>`<option value="${i}" ${e.refMonth===i?'selected':''}>${m}</option>`).join('');
    return `<span class="file-pill">
      <input class="proj-name" value="${e.projectName}" onchange="renameIdcFcstEntry(${e.id}, this.value)">
      · aba "${e.sheetUsed}" ·
      <select class="scale-select" onchange="rescaleIdcFcstEntry(${e.id}, this.value)">
        <option value="1" ${e.scale===1?'selected':''}>R$</option>
        <option value="1000000" ${e.scale===1000000?'selected':''}>R$ milhões</option>
      </select>
      · mês:
      <select class="scale-select" onchange="setIdcFcstRefMonth(${e.id}, this.value, null)"><option value="">—</option>${monthOptions}</select>
      <input type="number" class="scale-select" style="width:60px" value="${e.refYear}" onchange="setIdcFcstRefMonth(${e.id}, null, this.value)">
      <button onclick="removeIdcFcstEntry(${e.id})">✕</button>
    </span>`;
  }).join('')}</div>`;
}
function setIdcFcstRefMonth(id, month, year){
  const e = idcFcstEntries.find(x=>x.id===id);
  if(!e) return;
  if(month!==null) e.refMonth = month==='' ? null : parseInt(month);
  if(year!==null) e.refYear = parseInt(year);
  renderIdcFcstFileList();
  renderIdcFcstPreview();
}
function renameIdcFcstEntry(id, name){
  const e = idcFcstEntries.find(x=>x.id===id);
  if(e){ e.projectName = name.trim() || e.projectName; renderIdcFcstPreview(); }
}
function rescaleIdcFcstEntry(id, scale){
  const e = idcFcstEntries.find(x=>x.id===id);
  if(e){ e.scale = parseFloat(scale); renderIdcFcstPreview(); }
}
function removeIdcFcstEntry(id){
  idcFcstEntries = idcFcstEntries.filter(e=>e.id!==id);
  renderIdcFcstFileList();
  if(idcFcstEntries.some(e=>e.monthly)) renderIdcFcstPreview();
  else idcFcstResults.style.display = 'none';
}

function idcFcstRefKey(e){
  return (e.refMonth!==null && e.refMonth!==undefined) ? (e.refMonth+'-'+e.refYear) : null;
}
function idcFcstEntriesForActiveMonth(){
  const all = idcFcstEntries.filter(e=>e.monthly);
  if(idcFcstActiveMonth === 'all') return all;
  return all.filter(e=> idcFcstRefKey(e) === idcFcstActiveMonth);
}

function renderIdcFcstPreview(){
  const allValid = idcFcstEntries.filter(e=>e.monthly);
  if(!allValid.length){ idcFcstResults.style.display='none'; return; }
  idcFcstResults.style.display = 'block';

  // pills: one per distinct reference month tagged among the files, plus "Todas"
  const refKeys = Array.from(new Set(allValid.map(idcFcstRefKey).filter(Boolean)));
  refKeys.sort((a,b)=>{ const [ma,ya]=a.split('-').map(Number), [mb,yb]=b.split('-').map(Number); return (ya-yb)||(ma-mb); });
  if(!refKeys.includes(idcFcstActiveMonth) && idcFcstActiveMonth!=='all') idcFcstActiveMonth = 'all';
  document.getElementById('idcFcstMonthTabs').innerHTML = ['all', ...refKeys].map(k=>{
    const label = k==='all' ? 'Todas' : (()=>{ const [m,y]=k.split('-'); return MONTH_PT[parseInt(m)]+'/'+y; })();
    const active = k===idcFcstActiveMonth;
    return `<button class="btn ${active?'':'secondary'}" style="margin:0 6px 6px 0;" onclick="setIdcFcstActiveMonth('${k}')">${label}</button>`;
  }).join('');

  const validEntries = idcFcstEntriesForActiveMonth();
  if(!validEntries.length){
    document.getElementById('idcFcstTable').innerHTML = '<tbody><tr><td>Nenhum arquivo marcado com esse mês ainda.</td></tr></tbody>';
    return;
  }

  // union of all month keys across all units, chronological
  const allKeys = new Set();
  validEntries.forEach(e=>{
    e.monthly.previsto.forEach((v,k)=>allKeys.add(k));
    e.monthly.realFcst.forEach((v,k)=>allKeys.add(k));
  });
  const months = Array.from(allKeys).sort();

  const headCols = months.map(k=>{
    const [y,m] = k.split('-');
    return `<th colspan="2">${MONTH_PT[parseInt(m)-1].slice(0,3)}/${y.slice(2)}</th>`;
  }).join('');
  const subCols = months.map(()=>'<th>Previsto</th><th>Real+FCST*</th>').join('');

  const bodyRows = validEntries.map(e=>{
    const cells = months.map(k=>{
      const p = (e.monthly.previsto.get(k)||0) * e.scale;
      const rf = (e.monthly.realFcst.get(k)||0) * e.scale;
      return `<td class="num">${fmtCurrency(p)}</td><td class="num">${fmtCurrency(rf)}</td>`;
    }).join('');
    return `<tr><td>${e.projectName}</td>${cells}</tr>`;
  }).join('');

  document.getElementById('idcFcstTable').innerHTML = `
    <thead>
      <tr><th rowspan="2">Unidade</th>${headCols}</tr>
      <tr>${subCols}</tr>
    </thead>
    <tbody>${bodyRows}</tbody>
  `;

  // Forecast changed — refresh unit-mapping options and the Aderência calc, if applicable
  if(typeof idcRealEntries !== 'undefined' && idcRealEntries.some(e=>e.snapshot)){
    const allNegocios = Array.from(new Set(idcRealEntries.filter(e=>e.snapshot).flatMap(e=>e.snapshot.rows.map(r=>r.name))));
    renderIdcMappingTable(allNegocios);
  }
}
function setIdcFcstActiveMonth(key){
  idcFcstActiveMonth = key;
  renderIdcFcstPreview();
}

/* ---------- IDC - Custos tab (Gasto do Período / Real side, PDF) ---------- */
// pdf.js needs a separate "worker" script. When this HTML is opened directly from
// disk (file://), browsers block loading a worker from a different origin (the CDN),
// causing "Setting up fake worker failed". Fetching the script and running it from a
// same-origin Blob URL works around that restriction.
const PDF_WORKER_URL = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
let pdfWorkerReadyPromise = null;
function ensurePdfWorkerReady(){
  if(!pdfWorkerReadyPromise){
    pdfWorkerReadyPromise = fetch(PDF_WORKER_URL)
      .then(r=>r.text())
      .then(code=>{
        const blob = new Blob([code], { type:'application/javascript' });
        pdfjsLib.GlobalWorkerOptions.workerSrc = URL.createObjectURL(blob);
      })
      .catch(()=>{
        // last resort: point straight at the CDN (works when the page isn't opened via file://)
        pdfjsLib.GlobalWorkerOptions.workerSrc = PDF_WORKER_URL;
      });
  }
  return pdfWorkerReadyPromise;
}

function parseBRNumberOrNull(s){
  if(s===null || s===undefined) return null;
  const t = String(s).trim();
  if(t==='' || t==='-') return null;
  const n = parseFloat(t.replace(/\./g,'').replace(',', '.'));
  return isNaN(n) ? null : n;
}

function groupPdfRows(items){
  // group text items into rows by y position (tolerance) then sort each row by x
  const rows = [];
  items.forEach(it=>{
    let bucket = rows.find(r=> Math.abs(r.y - it.y) <= 2.5);
    if(!bucket){ bucket = { y: it.y, items: [] }; rows.push(bucket); }
    bucket.items.push(it);
  });
  rows.forEach(r=> r.items.sort((a,b)=>a.x-b.x));
  rows.sort((a,b)=> b.y - a.y); // top to bottom
  return rows;
}

async function parseRealizadoPdf(file){
  await ensurePdfWorkerReady();
  const buf = await file.arrayBuffer();
  const doc = await pdfjsLib.getDocument({ data: buf }).promise;

  let reportDate = null;
  let headerInfo = null; // {realizadoX, secondColX} — matched by column position, not fixed count
  const dataRows = [];
  let totalRow = null;

  for(let p=1; p<=doc.numPages; p++){
    const page = await doc.getPage(p);
    const content = await page.getTextContent();
    const items = content.items
      .map(it=>({ text: it.str, x: it.transform[4], y: it.transform[5] }))
      .filter(it=> it.text.trim() !== '');

    if(!reportDate){
      const fullText = items.map(i=>i.text).join(' ');
      const m = fullText.match(/(\d{2})\/(\d{2})\/(\d{4})/);
      if(m) reportDate = { day: parseInt(m[1]), month: parseInt(m[2]), year: parseInt(m[3]) };
    }

    const rows = groupPdfRows(items);
    rows.forEach(row=>{
      const rowText = row.items.map(i=>i.text).join(' ');
      if(!headerInfo){
        if(/NEGOCIO/i.test(rowText)){
          const negocioItem = row.items.find(i=>/NEGOCIO/i.test(i.text));
          const realizadoItem = row.items.find(i=>/Realizado/i.test(i.text));
          const sorted = row.items.slice().sort((a,b)=>a.x-b.x);
          const negocioIdx = sorted.indexOf(negocioItem);
          const secondCol = sorted[negocioIdx+1];
          if(negocioItem && realizadoItem && secondCol){
            headerInfo = { realizadoX: realizadoItem.x, secondColX: secondCol.x };
          }
        }
        return;
      }
      // find the item whose x-position best matches the "Realizado R$" header column —
      // works regardless of how many other columns the report happens to have.
      let best = null, bestDist = Infinity;
      row.items.forEach(it=>{
        const d = Math.abs(it.x - headerInfo.realizadoX);
        if(d < bestDist){ bestDist = d; best = it; }
      });
      if(!best || bestDist > 40) return;
      const val = parseBRNumberOrNull(best.text);
      if(val===null) return;
      const nameItems = row.items.filter(it=> it.x < headerInfo.secondColX - 3);
      const name = nameItems.map(i=>i.text).join(' ').replace(/\s+/g,' ').trim();
      if(!name) return;
      if(/total geral/i.test(name)){ totalRow = { name, realizado: val }; return; }
      dataRows.push({ name, realizado: val });
    });
  }

  if(!dataRows.length){
    throw new Error('Não encontrei a tabela "Orçamento x Comprometido das Obras" (coluna "Realizado R$") neste PDF.');
  }

  // Default guess only — these snapshots are usually dated early in the month AFTER
  // the one they close (e.g. report on 02/06 closes Maio). The person confirms/edits
  // the actual month via the picker next to each uploaded file.
  let guessMonthIndex = null, guessYear = null;
  if(reportDate){
    guessMonthIndex = reportDate.month - 2; // 0-based month, minus one more for "closes prior month"
    guessYear = reportDate.year;
    if(guessMonthIndex < 0){ guessMonthIndex = 11; guessYear -= 1; }
  }

  return { reportDate, guessMonthIndex, guessYear, rows: dataRows, totalRow };
}

const idcRealDrop = document.getElementById('idcRealDrop');
const idcRealFile = document.getElementById('idcRealFile');
const idcRealFileList = document.getElementById('idcRealFileList');
const idcRealProgress = document.getElementById('idcRealProgress');
const idcRealError = document.getElementById('idcRealError');
const idcRealResults = document.getElementById('idcRealResults');

let idcRealEntries = []; // {id, name, snapshot:{reportDate,refMonthIndex,refYear,rows,totalRow}, error}
let idcRealEntrySeq = 0;
let idcMapping = {}; // negocioName -> forecast projectName ('' = não mapear)

idcRealDrop.addEventListener('click', ()=> idcRealFile.click());
idcRealDrop.addEventListener('dragover', e=>{ e.preventDefault(); idcRealDrop.classList.add('drag'); });
idcRealDrop.addEventListener('dragleave', ()=> idcRealDrop.classList.remove('drag'));
idcRealDrop.addEventListener('drop', e=>{
  e.preventDefault(); idcRealDrop.classList.remove('drag');
  if(e.dataTransfer.files.length) handleIdcRealFiles(Array.from(e.dataTransfer.files));
});
idcRealFile.addEventListener('change', e=>{
  if(e.target.files.length) handleIdcRealFiles(Array.from(e.target.files));
  idcRealFile.value = '';
});

async function handleIdcRealFiles(files){
  idcRealError.innerHTML = '';
  for(const file of files){
    const entry = { id: ++idcRealEntrySeq, name: file.name, snapshot: null, error: null };
    idcRealEntries.push(entry);
    idcRealProgress.innerHTML = `<div class="progress-item"><span class="spinner"></span> Lendo ${file.name}…</div>`;
    await new Promise(r=>setTimeout(r,0));
    try{
      entry.snapshot = await parseRealizadoPdf(file);
      entry.monthIndex = entry.snapshot.guessMonthIndex ?? 0; // no date found — defaults to Jan, user picks the right one
      entry.year = entry.snapshot.guessYear ?? new Date().getFullYear();
    }catch(err){
      entry.error = err.message;
    }
    renderIdcRealFileList();
    await new Promise(r=>setTimeout(r,0));
  }
  idcRealProgress.innerHTML = '';
  renderIdcRealPreview();
}

function renderIdcRealFileList(){
  if(!idcRealEntries.length){ idcRealFileList.innerHTML=''; return; }
  idcRealFileList.innerHTML = `<div class="file-list">${idcRealEntries.map(e=>{
    if(e.error) return `<span class="file-pill error">${e.name} · erro: ${e.error} <button onclick="removeIdcRealEntry(${e.id})">✕</button></span>`;
    if(!e.snapshot) return `<span class="file-pill">${e.name} · lendo… <button onclick="removeIdcRealEntry(${e.id})">✕</button></span>`;
    const s = e.snapshot;
    const monthOptions = MONTH_PT.map((m,i)=>`<option value="${i}" ${e.monthIndex===i?'selected':''}>${m}</option>`).join('');
    return `<span class="file-pill">${e.name} · relatório ${String(s.reportDate.day).padStart(2,'0')}/${String(s.reportDate.month).padStart(2,'0')}/${s.reportDate.year} · mês:
      <select class="scale-select" onchange="setIdcRealEntryMonth(${e.id}, this.value, null)">${monthOptions}</select>
      <input type="number" class="scale-select" style="width:60px" value="${e.year}" onchange="setIdcRealEntryMonth(${e.id}, null, this.value)">
      · ${s.rows.length} negócios <button onclick="removeIdcRealEntry(${e.id})">✕</button></span>`;
  }).join('')}</div>`;
}
function setIdcRealEntryMonth(id, monthIndex, year){
  const e = idcRealEntries.find(x=>x.id===id);
  if(!e) return;
  if(monthIndex!==null) e.monthIndex = parseInt(monthIndex);
  if(year!==null) e.year = parseInt(year);
  renderIdcRealPreview();
}
function removeIdcRealEntry(id){
  idcRealEntries = idcRealEntries.filter(e=>e.id!==id);
  renderIdcRealFileList();
  renderIdcRealPreview();
}

function renderIdcRealPreview(){
  const valid = idcRealEntries.filter(e=>e.snapshot);
  if(!valid.length){ idcRealResults.style.display='none'; computeIdcAderencia(); return; }
  idcRealResults.style.display = 'block';

  const entries = valid.slice().sort((a,b)=> (a.year-b.year) || (a.monthIndex-b.monthIndex));
  const headCols = entries.map(e=>`<th>${MONTH_PT[e.monthIndex].slice(0,3)}/${e.year}</th>`).join('');

  const allNegocios = Array.from(new Set(entries.flatMap(e=>e.snapshot.rows.map(r=>r.name))));
  const bodyRows = allNegocios.map(name=>{
    const cells = entries.map(e=>{
      const row = e.snapshot.rows.find(r=>r.name===name);
      return `<td class="num">${row? fmtCurrency(row.realizado) : '—'}</td>`;
    }).join('');
    return `<tr><td>${name}</td>${cells}</tr>`;
  }).join('');

  document.getElementById('idcRealTable').innerHTML = `
    <thead><tr><th>Negócio</th>${headCols}</tr></thead>
    <tbody>${bodyRows}</tbody>
  `;

  renderIdcMappingTable(allNegocios);
}

function normalizeForMatch(s){
  return String(s||'').toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^A-Z0-9]+/g,' ').trim().split(' ').filter(Boolean);
}
function guessMapping(negocioName, forecastNames){
  const nTokens = normalizeForMatch(negocioName);
  let best = '', bestScore = 0;
  forecastNames.forEach(fn=>{
    const fTokens = normalizeForMatch(fn);
    const score = fTokens.filter(t=>nTokens.includes(t)).length;
    if(score > bestScore){ bestScore = score; best = fn; }
  });
  return bestScore > 0 ? best : '';
}

// Fornecedores dictionary (Razão Social x Nome Fantasia -> Cod. Fornecedor) — lets NEJ
// resolve names that share no text at all (ex: "GESSO MT" vs "M. P. Brito & S. M. Pontes
// Gesso Ltda") by matching them to the same supplier code instead of comparing text.
function normalizeExact(s){
  return String(s||'').toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^A-Z0-9]+/g,' ').trim();
}
