/* ---------- Treinamentos tab ---------- */
const REQUIRED_TRN_COLS = ['departamento','obj_custo_func','descricao','status','vencido'];

const trnDrop = document.getElementById('trnDrop');
const trnFile = document.getElementById('trnFile');
const trnFileList = document.getElementById('trnFileList');
const trnProgress = document.getElementById('trnProgress');
const trnError = document.getElementById('trnError');
const trnResults = document.getElementById('trnResults');
const trnDedupInfo = document.getElementById('trnDedupInfo');

let trnEntries = [];
let trnEntrySeq = 0;
let trnLastData = null;

trnDrop.addEventListener('click', ()=> trnFile.click());
trnDrop.addEventListener('dragover', e=>{ e.preventDefault(); trnDrop.classList.add('drag'); });
trnDrop.addEventListener('dragleave', ()=> trnDrop.classList.remove('drag'));
trnDrop.addEventListener('drop', e=>{
  e.preventDefault(); trnDrop.classList.remove('drag');
  if(e.dataTransfer.files.length) handleTrnFiles(Array.from(e.dataTransfer.files));
});
trnFile.addEventListener('change', e=>{
  if(e.target.files.length) handleTrnFiles(Array.from(e.target.files));
  trnFile.value = '';
});
document.getElementById('trnClearAll').addEventListener('click', ()=>{
  trnEntries = [];
  trnResults.style.display = 'none';
  trnDedupInfo.innerHTML = '';
  renderTrnFileList();
});
document.getElementById('trnRecalc').addEventListener('click', ()=> combineAndRenderTrn());
document.getElementById('trnItielList').addEventListener('change', ()=> combineAndRenderTrn());

async function handleTrnFiles(files){
  trnError.innerHTML = '';
  for(const file of files){
    const entry = { id: ++trnEntrySeq, name: file.name, rows: null, count: 0, error: null };
    trnEntries.push(entry);
    trnProgress.innerHTML = `<div class="progress-item"><span class="spinner"></span> Lendo ${file.name} (pode levar alguns segundos em bases grandes)…</div>`;
    await new Promise(r=>setTimeout(r,0));
    try{
      const matrix = await readWorkbookMatrix(file);
      const rows = parseWithHeaderDetection(matrix, REQUIRED_TRN_COLS);
      if(!rows){
        entry.error = 'Não encontrei as colunas departamento, obj_custo_func, descricao, status e vencido.';
      } else {
        entry.rows = rows;
        entry.count = rows.length;
      }
    }catch(err){
      entry.error = err.message;
    }
    renderTrnFileList();
    await new Promise(r=>setTimeout(r,0));
  }
  trnProgress.innerHTML = '';
  combineAndRenderTrn();
}

function renderTrnFileList(){
  if(!trnEntries.length){ trnFileList.innerHTML=''; return; }
  trnFileList.innerHTML = `<div class="file-list">${trnEntries.map(e=>{
    if(e.error) return `<span class="file-pill error">${e.name} · erro: ${e.error} <button onclick="removeTrnEntry(${e.id})">✕</button></span>`;
    if(!e.rows) return `<span class="file-pill">${e.name} · lendo… <button onclick="removeTrnEntry(${e.id})">✕</button></span>`;
    return `<span class="file-pill">${e.name} · ${e.count.toLocaleString('pt-BR')} linhas <button onclick="removeTrnEntry(${e.id})">✕</button></span>`;
  }).join('')}</div>`;
}
function removeTrnEntry(id){
  trnEntries = trnEntries.filter(e=>e.id!==id);
  renderTrnFileList();
  if(trnEntries.some(e=>e.rows)) combineAndRenderTrn();
  else { trnResults.style.display='none'; trnDedupInfo.innerHTML=''; }
}

function combineAndRenderTrn(){
  const allRows = [];
  trnEntries.forEach(e=>{ if(e.rows) allRows.push(...e.rows); });
  if(!allRows.length){ trnResults.style.display='none'; return; }

  const keyCols = Object.keys(allRows[0]).sort();
  const seen = new Set();
  const finalRows = [];
  let dupCount = 0;
  allRows.forEach(r=>{
    const sig = keyCols.map(c=> r[c] instanceof Date ? r[c].getTime() : r[c]).join('|');
    if(seen.has(sig)){ dupCount++; return; }
    seen.add(sig);
    finalRows.push(r);
  });
  trnDedupInfo.innerHTML = dupCount
    ? `<div class="info-box">${dupCount.toLocaleString('pt-BR')} linha(s) idêntica(s) repetida(s) entre os arquivos — contadas uma única vez.</div>`
    : '';

  renderTrn(finalRows);
}

function calcTrnBlock(rows){
  const total = rows.length;
  let concluidos = 0, noPrazo = 0, foraPrazo = 0;
  rows.forEach(r=>{
    const status = String(r['status']||'').trim();
    if(status !== 'Concluido') return;
    concluidos++;
    const vRaw = r['vencido'];
    if(vRaw===null || vRaw===undefined || vRaw===''){ noPrazo++; return; } // blank counts as "no prazo"
    const v = parseFloat(vRaw);
    if(isNaN(v) || v<=0) noPrazo++;
    else foraPrazo++;
  });
  return { total, concluidos, noPrazo, foraPrazo };
}

function trnCardsHtml(block, meta){
  const pctConcl = block.total ? block.concluidos/block.total : 0;
  const pctNoPrazo = block.total ? block.noPrazo/block.total : 0;
  const pctFora = block.total ? block.foraPrazo/block.total : 0;
  const ok = pctNoPrazo >= meta;
  return `
    <div class="card"><div class="lbl">Quantidade Total</div><div class="val">${block.total.toLocaleString('pt-BR')}</div></div>
    <div class="card"><div class="lbl">Concluídos</div><div class="val">${fmtPct(pctConcl)}</div><div class="sub">${block.concluidos.toLocaleString('pt-BR')}</div></div>
    <div class="card ${ok?'':'accent'}"><div class="lbl">Concluídos no Prazo</div><div class="val">${fmtPct(pctNoPrazo)}</div>
      <div class="sub">${block.noPrazo.toLocaleString('pt-BR')} · <span class="badge ${ok?'ok':'fail'}">${ok?'Dentro da meta':'Fora da meta'}</span></div></div>
    <div class="card"><div class="lbl">Concluídos Fora do Prazo</div><div class="val">${fmtPct(pctFora)}</div><div class="sub">${block.foraPrazo.toLocaleString('pt-BR')}</div></div>
  `;
}

function renderTrn(rows){
  const meta = (parseFloat(document.getElementById('trnMeta').value) || 90) / 100;
  const itielIds = document.getElementById('trnItielList').value
    .split(',').map(s=>s.trim()).filter(Boolean).map(s=>String(parseInt(s)));

  const itielRows = rows.filter(r=> itielIds.includes(String(parseInt(r['obj_custo_func']))));

  const geral = calcTrnBlock(rows);
  const itiel = calcTrnBlock(itielRows);

  document.getElementById('trnCardsGeral').innerHTML = trnCardsHtml(geral, meta);
  document.getElementById('trnCardsItiel').innerHTML = trnCardsHtml(itiel, meta);

  // Top 5 pendências (Itiel only): status != Concluido
  const pendentes = itielRows.filter(r=> String(r['status']||'').trim() !== 'Concluido');
  function topN(rows, field, n){
    const counts = new Map();
    rows.forEach(r=>{
      const key = String(r[field]||'').trim() || '(vazio)';
      counts.set(key, (counts.get(key)||0)+1);
    });
    return Array.from(counts.entries()).sort((a,b)=>b[1]-a[1]).slice(0,n);
  }
  const topCursos = topN(pendentes, 'descricao', 5);
  const topDeptos = topN(pendentes, 'departamento', 5);

  document.getElementById('trnTopCursos').innerHTML = `
    <thead><tr><th>Curso</th><th>Pendências</th></tr></thead>
    <tbody>${topCursos.map(([name,c])=>`<tr><td>${name}</td><td class="num">${c}</td></tr>`).join('') || '<tr><td colspan="2">Sem dados</td></tr>'}</tbody>
  `;
  document.getElementById('trnTopDeptos').innerHTML = `
    <thead><tr><th>Departamento</th><th>Pendências</th></tr></thead>
    <tbody>${topDeptos.map(([name,c])=>`<tr><td>${name}</td><td class="num">${c}</td></tr>`).join('') || '<tr><td colspan="2">Sem dados</td></tr>'}</tbody>
  `;

  trnResults.style.display = 'block';
  trnLastData = { meta, geral, itiel, topCursos, topDeptos };
}

document.getElementById('trnExportPdf').addEventListener('click', ()=>{
  if(!trnLastData) return;
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit:'pt', format:'a4' });
  const d = trnLastData;
  const today = new Date().toLocaleDateString('pt-BR');

  doc.setFont('helvetica','bold'); doc.setFontSize(16); doc.setTextColor(48,79,126);
  doc.text('Treinamentos', 40, 44);
  doc.setFont('helvetica','normal'); doc.setFontSize(9); doc.setTextColor(110,110,110);
  doc.text(`Gerado em ${today} · meta de conclusão no prazo: ${(d.meta*100).toFixed(0)}%`, 40, 60);

  function cardBlock(doc, y, title, b){
    doc.setFont('helvetica','bold'); doc.setFontSize(11); doc.setTextColor(48,79,126);
    doc.text(title, 40, y);

    const cardData = [
      { lbl:'QUANTIDADE TOTAL', val: b.total.toLocaleString('pt-BR'), sub:'', accent:false },
      { lbl:'CONCLUÍDOS', val: fmtPct(b.total? b.concluidos/b.total:0), sub: b.concluidos.toLocaleString('pt-BR'), accent:false },
      { lbl:'CONCLUÍDOS NO PRAZO', val: fmtPct(b.total? b.noPrazo/b.total:0), sub: b.noPrazo.toLocaleString('pt-BR')+' · '+((b.total? b.noPrazo/b.total:0)>=d.meta?'Dentro da meta':'Fora da meta'), accent:true },
      { lbl:'CONCLUÍDOS FORA DO PRAZO', val: fmtPct(b.total? b.foraPrazo/b.total:0), sub: b.foraPrazo.toLocaleString('pt-BR'), accent:false },
    ];
    const cardY = y+14, cardH = 54, gap = 10, marginX = 40;
    const cardW = (515 - gap*3) / 4;
    cardData.forEach((c,i)=>{
      const x = marginX + i*(cardW+gap);
      doc.setDrawColor(228,230,234); doc.setFillColor(255,255,255);
      doc.roundedRect(x, cardY, cardW, cardH, 5, 5, 'FD');
      doc.setFont('helvetica','bold'); doc.setFontSize(6.5); doc.setTextColor(107,114,128);
      doc.text(c.lbl, x+8, cardY+15);
      doc.setFont('helvetica','bold'); doc.setFontSize(15);
      doc.setTextColor(...(c.accent ? [234,162,57] : [33,55,88]));
      doc.text(c.val, x+8, cardY+33);
      if(c.sub){
        doc.setFont('helvetica','normal'); doc.setFontSize(6.5); doc.setTextColor(107,114,128);
        doc.text(c.sub, x+8, cardY+45);
      }
    });
    return cardY + cardH;
  }

  let y = cardBlock(doc, 84, 'Indicadores Gerais (todos os treinamentos)', d.geral);
  y = cardBlock(doc, y+26, 'Indicadores Itiel', d.itiel);

  doc.setFont('helvetica','bold'); doc.setFontSize(11); doc.setTextColor(48,79,126);
  doc.text('Top 5 cursos com mais pendência (Itiel)', 40, y+30);
  doc.autoTable({
    startY: y+38,
    head: [['Curso','Pendências']],
    body: d.topCursos,
    headStyles:{fillColor:[48,79,126],textColor:255,fontStyle:'bold'},
    styles:{font:'helvetica',fontSize:9,cellPadding:5}, theme:'grid',
  });
  const y3 = doc.lastAutoTable.finalY;
  doc.setFont('helvetica','bold'); doc.setFontSize(11); doc.setTextColor(48,79,126);
  doc.text('Top 5 departamentos com mais pendência (Itiel)', 40, y3+24);
  doc.autoTable({
    startY: y3+32,
    head: [['Departamento','Pendências']],
    body: d.topDeptos,
    headStyles:{fillColor:[48,79,126],textColor:255,fontStyle:'bold'},
    styles:{font:'helvetica',fontSize:9,cellPadding:5}, theme:'grid',
  });

  doc.save(`Treinamentos_${new Date().toISOString().slice(0,10)}.pdf`);
});

/* ---------- NEJ - Consolidado tab ---------- */
const nejResults = document.getElementById('nejResults');
let nejLastData = null;
let nejEdits = {}; // editKey (unit|||empresaOriginal) -> {name, removed}
let nejMatchOverrides = {}; // editKey -> monday key ('unidade|||empresa') or '' for manually unmatched

/* Monthly pre-processed spreadsheet (Unidade/Empresa/Ano/Mês/Previsto/Realizado),
   generated outside the browser from the .mpp — this is now the only input path. */
const REQUIRED_NEJ_MONTHLY_COLS = ['unidade','empresa','ano','mês','realizado'];
const nejMonthlyDrop = document.getElementById('nejMonthlyDrop');
const nejMonthlyFile = document.getElementById('nejMonthlyFile');
const nejMonthlyFileList = document.getElementById('nejMonthlyFileList');
const nejMonthlyProgress = document.getElementById('nejMonthlyProgress');
const nejMonthlyError = document.getElementById('nejMonthlyError');
let nejMonthlyEntries = []; // {id, name, rows:[{unit,empresa,previsto,realizado,ano,mes}], error}
let nejMonthlyEntrySeq = 0;

nejMonthlyDrop.addEventListener('click', ()=> nejMonthlyFile.click());
nejMonthlyDrop.addEventListener('dragover', e=>{ e.preventDefault(); nejMonthlyDrop.classList.add('drag'); });
nejMonthlyDrop.addEventListener('dragleave', ()=> nejMonthlyDrop.classList.remove('drag'));
nejMonthlyDrop.addEventListener('drop', e=>{
  e.preventDefault(); nejMonthlyDrop.classList.remove('drag');
  if(e.dataTransfer.files.length) handleNejMonthlyFiles(Array.from(e.dataTransfer.files));
});
nejMonthlyFile.addEventListener('change', e=>{
  if(e.target.files.length) handleNejMonthlyFiles(Array.from(e.target.files));
  nejMonthlyFile.value = '';
});

async function handleNejMonthlyFiles(files){
  nejMonthlyError.innerHTML = '';
  for(const file of files){
    const entry = { id: ++nejMonthlyEntrySeq, name: file.name, rows: null, error: null };
    nejMonthlyEntries.push(entry);
    nejMonthlyProgress.innerHTML = `<div class="progress-item"><span class="spinner"></span> Lendo ${file.name}…</div>`;
    await new Promise(r=>setTimeout(r,0));
    try{
      const matrix = await readWorkbookMatrix(file);
      const rawRows = parseWithHeaderDetection(matrix, REQUIRED_NEJ_MONTHLY_COLS);
      if(!rawRows){
        entry.error = 'Não encontrei as colunas Unidade, Empresa, Ano, Mês e Realizado.';
      } else {
        // "Previsto" header varies a bit (ex: "Previsto (Cota)") — match loosely by substring
        const sampleKeys = rawRows.length ? Object.keys(rawRows[0]) : [];
        const previstoKey = sampleKeys.find(k=> k.includes('previsto')) || 'previsto';
        entry.rows = rawRows.map(r=>({
          unit: String(r['unidade']||'').trim(),
          empresa: String(r['empresa']||'').trim(),
          ano: parseInt(r['ano']),
          mes: parseInt(r['mês']),
          previsto: parseFloat(r[previstoKey]) || 0,
          realizado: parseFloat(r['realizado']) || 0,
        })).filter(r=> r.unit && r.empresa && !isNaN(r.ano) && !isNaN(r.mes));
        if(!entry.rows.length) entry.error = 'Nenhuma linha válida encontrada (confira Ano/Mês numéricos).';
      }
    }catch(err){
      entry.error = err.message;
    }
    renderNejMonthlyFileList();
    await new Promise(r=>setTimeout(r,0));
  }
  nejMonthlyProgress.innerHTML = '';
  combineAndRenderNej();
}

function renderNejMonthlyFileList(){
  if(!nejMonthlyEntries.length){ nejMonthlyFileList.innerHTML=''; return; }
  nejMonthlyFileList.innerHTML = `<div class="file-list">${nejMonthlyEntries.map(e=>{
    if(e.error) return `<span class="file-pill error">${e.name} · erro: ${e.error} <button onclick="removeNejMonthlyEntry(${e.id})">✕</button></span>`;
    if(!e.rows) return `<span class="file-pill">${e.name} · lendo… <button onclick="removeNejMonthlyEntry(${e.id})">✕</button></span>`;
    const units = new Set(e.rows.map(r=>r.unit));
    return `<span class="file-pill">${e.name} · ${e.rows.length.toLocaleString('pt-BR')} linhas · ${units.size} unidade(s) <button onclick="removeNejMonthlyEntry(${e.id})">✕</button></span>`;
  }).join('')}</div>`;
}
function removeNejMonthlyEntry(id){
  nejMonthlyEntries = nejMonthlyEntries.filter(e=>e.id!==id);
  renderNejMonthlyFileList();
  combineAndRenderNej();
}

// Monday.com — file storage only for now, pending a sample to map the format
const nejMondayDrop = document.getElementById('nejMondayDrop');
const nejMondayFile = document.getElementById('nejMondayFile');
const nejMondayFileList = document.getElementById('nejMondayFileList');
let nejMondayEntries = [];
let nejMondayEntrySeq = 0;

const REQUIRED_MONDAY_COLS = ['tipo_de_aditivo','empresa','unidade','status'];

nejMondayDrop.addEventListener('click', ()=> nejMondayFile.click());
nejMondayDrop.addEventListener('dragover', e=>{ e.preventDefault(); nejMondayDrop.classList.add('drag'); });
nejMondayDrop.addEventListener('dragleave', ()=> nejMondayDrop.classList.remove('drag'));
nejMondayDrop.addEventListener('drop', e=>{
  e.preventDefault(); nejMondayDrop.classList.remove('drag');
  if(e.dataTransfer.files.length) handleNejMondayFiles(Array.from(e.dataTransfer.files));
});
nejMondayFile.addEventListener('change', e=>{
  if(e.target.files.length) handleNejMondayFiles(Array.from(e.target.files));
  nejMondayFile.value = '';
});

async function handleNejMondayFiles(files){
  document.getElementById('nejMondayError').innerHTML = '';
  for(const file of files){
    const entry = { id: ++nejMondayEntrySeq, name: file.name, rows: null, error: null };
    nejMondayEntries.push(entry);
    renderNejMondayFileList();
    await new Promise(r=>setTimeout(r,0));
    try{
      const matrix = await readWorkbookMatrix(file);
      const allRows = parseWithHeaderDetection(matrix, REQUIRED_MONDAY_COLS);
      if(!allRows){
        entry.error = 'Não encontrei as colunas Tipo de Aditivo, Empresa, Unidade e Status.';
      } else {
        // only the "Notificação Extrajudicial" rows matter for NEJ — other Aditivo types
        // (Remoção de Saldo, Alteração de Prazo, etc.) share this same board but aren't relevant here.
        entry.rows = allRows.filter(r=> String(r['tipo_de_aditivo']||'').trim().toLowerCase() === 'notificação extrajudicial');
      }
    }catch(err){
      entry.error = err.message;
    }
    renderNejMondayFileList();
    await new Promise(r=>setTimeout(r,0));
  }
  combineAndRenderNejMonday();
}

function renderNejMondayFileList(){
  if(!nejMondayEntries.length){ nejMondayFileList.innerHTML=''; return; }
  nejMondayFileList.innerHTML = `<div class="file-list">${nejMondayEntries.map(e=>{
    if(e.error) return `<span class="file-pill error">${e.name} · erro: ${e.error} <button onclick="removeNejMondayEntry(${e.id})">✕</button></span>`;
    if(!e.rows) return `<span class="file-pill">${e.name} · lendo… <button onclick="removeNejMondayEntry(${e.id})">✕</button></span>`;
    return `<span class="file-pill">${e.name} · ${e.rows.length.toLocaleString('pt-BR')} notificações extrajudiciais <button onclick="removeNejMondayEntry(${e.id})">✕</button></span>`;
  }).join('')}</div>`;
}
function removeNejMondayEntry(id){
  nejMondayEntries = nejMondayEntries.filter(e=>e.id!==id);
  renderNejMondayFileList();
  combineAndRenderNejMonday();
}

let nejMondayGrouped = [];

function fmtDateBR(d){
  if(!d || !(d instanceof Date) || isNaN(d)) return '—';
  return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear();
}

// Monday's board covers all 14 units, but its unit labels ("2-Nova Mutum") don't match
// the Project-derived names ("Nova Mutum") exactly — strip numeric prefixes/punctuation
// and compare loosely so we can scope suggestions (and exports) to the same unit.
function normalizeUnitName(s){
  return String(s||'').toUpperCase()
    .replace(/^\d+\s*-?\s*/, '') // drop a leading "2-" / "2 - " style prefix
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^A-Z0-9]+/g,' ').trim();
}
function unitsMatch(projectUnit, mondayUnit){
  const a = normalizeUnitName(projectUnit), b = normalizeUnitName(mondayUnit);
  if(!a || !b) return false;
  return a.includes(b) || b.includes(a);
}
function mondayCandidatesForUnit(projectUnit){
  const scoped = nejMondayGrouped.filter(g=> unitsMatch(projectUnit, g.unidade));
  return scoped.length ? scoped : nejMondayGrouped; // fall back to everything if nothing matches
}

function combineAndRenderNejMonday(){
  const allRows = [];
  nejMondayEntries.forEach(e=>{ if(e.rows) allRows.push(...e.rows); });

  // group by unidade + empresa; keep every status/motivo seen for that pair
  const grouped = new Map();
  allRows.forEach(r=>{
    const unidade = String(r['unidade']||'').trim();
    const empresa = String(r['empresa']||'').trim();
    if(!empresa) return;
    const k = unidade+'|||'+empresa;
    if(!grouped.has(k)) grouped.set(k, { unidade, empresa, entries: [] });
    grouped.get(k).entries.push({
      status: String(r['status']||'').trim(),
      motivo: String(r['motivo_da_notificação']||'').trim(),
      area: String(r['área_responsável_pelo_atraso']||'').trim(),
      dataAberturaJur: parseFlexDate(r['data_de_abertura_jur']),
      dataEscrituracao: parseFlexDate(r['data_escrituração']),
    });
  });

  nejMondayGrouped = Array.from(grouped.values()).map(g=>{
    const formalizado = g.entries.some(e=> e.status.startsWith('4-'));
    const cancelado = !formalizado && g.entries.every(e=> e.status.startsWith('5-'));
    const situacao = formalizado ? 'Formalizado' : (cancelado ? 'Cancelado' : 'Em andamento');
    // most recent notification-opening date and (if formalized) formalization date, across all entries for this pair
    const aberturaDates = g.entries.map(e=>e.dataAberturaJur).filter(Boolean);
    const escrituraDates = g.entries.map(e=>e.dataEscrituracao).filter(Boolean);
    const dataAbertura = aberturaDates.length ? new Date(Math.max(...aberturaDates.map(d=>d.getTime()))) : null;
    const dataEscritura = escrituraDates.length ? new Date(Math.max(...escrituraDates.map(d=>d.getTime()))) : null;
    return { ...g, situacao, dataAbertura, dataEscritura };
  });
  nejMondayGrouped.sort((a,b)=> a.unidade.localeCompare(b.unidade) || a.empresa.localeCompare(b.empresa));

  document.getElementById('nejMondayTable').innerHTML = `
    <thead><tr><th>Unidade</th><th>Empresa</th><th>Ocorrências</th><th>Motivo(s)</th><th>Abertura JUR</th><th>Escrituração</th><th>Situação</th></tr></thead>
    <tbody>${nejMondayGrouped.map(g=>{
      const motivos = Array.from(new Set(g.entries.map(e=>e.motivo).filter(Boolean))).join(', ') || '—';
      const badgeClass = g.situacao==='Formalizado' ? 'ok' : (g.situacao==='Cancelado' ? 'fail' : '');
      return `<tr>
        <td>${g.unidade}</td><td>${g.empresa}</td><td class="num">${g.entries.length}</td><td>${motivos}</td>
        <td>${fmtDateBR(g.dataAbertura)}</td><td>${fmtDateBR(g.dataEscritura)}</td>
        <td><span class="badge ${badgeClass}">${g.situacao}</span></td>
      </tr>`;
    }).join('') || '<tr><td colspan="7">Sem dados</td></tr>'}</tbody>
  `;

  // Monday data feeds the auto-match column in the Project table — refresh it too
  if(nejMonthlyEntries.some(e=>e.rows)) combineAndRenderNej();
}

document.getElementById('nejClearAll').addEventListener('click', ()=>{
  nejMonthlyEntries = [];
  nejEdits = {};
  nejResults.style.display = 'none';
  renderNejMonthlyFileList();
});
document.getElementById('nejRecalc').addEventListener('click', ()=> combineAndRenderNej());
document.getElementById('nejMonthSelect').addEventListener('change', ()=> combineAndRenderNej());
document.getElementById('nejExcludeList').addEventListener('change', ()=> combineAndRenderNej());

function combineAndRenderNej(){
  const validMonthlyEntries = nejMonthlyEntries.filter(e=>e.rows);
  if(!validMonthlyEntries.length){ nejResults.style.display='none'; return; }
  nejResults.style.display = 'block';

  const excludeList = document.getElementById('nejExcludeList').value
    .split(',').map(s=>s.trim().toUpperCase()).filter(Boolean);
  const meta = parseFloat(document.getElementById('nejMeta').value);
  const metaVal = isNaN(meta) ? -5 : meta;

  // every (ano, mês) combo present in the uploaded sheets, so the person can pick
  // which month to analyze if more than one has been uploaded over time
  const allMonthly = [];
  validMonthlyEntries.forEach(e=> allMonthly.push(...e.rows));
  const monthKeys = Array.from(new Set(allMonthly.map(r=> r.ano+'-'+String(r.mes).padStart(2,'0')))).sort();

  const monthSelect = document.getElementById('nejMonthSelect');
  const prevSelected = monthSelect.value;
  monthSelect.innerHTML = monthKeys.map(k=>{
    const [y,m] = k.split('-');
    return `<option value="${k}">${MONTH_PT[parseInt(m)-1]}/${y}</option>`;
  }).join('');
  const selectedKey = monthKeys.includes(prevSelected) ? prevSelected : monthKeys[monthKeys.length-1];
  monthSelect.value = selectedKey;

  const rowsForMonth = allMonthly.filter(r=> (r.ano+'-'+String(r.mes).padStart(2,'0')) === selectedKey);

  const agg = new Map(); // unit|||empresa -> {unit, empresaOriginal, bcws, bcwp, periodLabel}
  rowsForMonth.forEach(r=>{
    if(excludeList.includes(r.empresa.toUpperCase())) return;
    const k = r.unit+'|||'+r.empresa;
    const label = `${MONTH_PT[r.mes-1]||r.mes}/${r.ano}`;
    if(agg.has(k)){
      const existing = agg.get(k);
      existing.bcws += r.previsto; existing.bcwp += r.realizado;
    } else {
      agg.set(k, { unit: r.unit, empresaOriginal: r.empresa, bcws: r.previsto, bcwp: r.realizado, periodLabel: label });
    }
  });

  // apply manual edits (rename / remove) — keyed by unit+original name so they survive recalcs
  const allMapped = Array.from(agg.values())
    .map(a=>{
      const editKey = a.unit+'|||'+a.empresaOriginal;
      const edit = nejEdits[editKey] || {};
      return {
        ...a, editKey,
        empresa: edit.name || a.empresaOriginal,
        removed: !!edit.removed,
        justificativa: edit.justificativa || '',
        dev: a.bcws ? (a.bcwp-a.bcws)/a.bcws*100 : 0,
      };
    });
  const removedRows = allMapped.filter(r=>r.removed);
  let results = allMapped.filter(r=> !r.removed);
  results.sort((a,b)=> a.unit.localeCompare(b.unit) || a.dev - b.dev);

  const flagged = results.filter(r=> r.dev < metaVal);

  // Match each Project company against the Monday list (auto by text similarity,
  // manual override wins when the person picks something in the dropdown).
  results.forEach(r=>{
    const candidates = mondayCandidatesForUnit(r.unit);
    const candidateNames = Array.from(new Set(candidates.map(g=>g.empresa)));
    const override = nejMatchOverrides[r.editKey];
    if(override !== undefined){
      r.mondayMatch = override === '' ? null : nejMondayGrouped.find(g=> (g.unidade+'|||'+g.empresa) === override) || null;
      r.mondayAuto = false;
    } else if(candidateNames.length){
      const guess = guessMappingWithDict(r.empresa, candidateNames);
      r.mondayMatch = guess ? candidates.find(g=>g.empresa===guess) : null;
      r.mondayAuto = true;
    } else {
      r.mondayMatch = null;
      r.mondayAuto = true;
    }
  });

  // Notificado exige um registro no Monday cuja data (Abertura JUR ou Escrituração)
  // caia dentro da janela: do início do 2º mês anterior até o fim do mês analisado.
  // Ex: analisando Junho, a janela vai de 01/Abril a 30/Junho — uma notificação de
  // antes de abril não conta como cobrindo o desvio de junho.
  const [selYear, selMonthNum] = selectedKey.split('-').map(Number);
  const windowStart = new Date(selYear, selMonthNum-1-2, 1);
  const windowEnd = new Date(selYear, selMonthNum, 0, 23, 59, 59);
  function mondayEntryInWindow(g){
    if(!g) return false;
    return g.entries.some(e=>{
      const d1 = e.dataAberturaJur, d2 = e.dataEscrituracao;
      const inRange = d => d && d >= windowStart && d <= windowEnd;
      return inRange(d1) || inRange(d2);
    });
  }
  const finalRows = flagged.map(r=>{
    const notificadoNaJanela = mondayEntryInWindow(r.mondayMatch);
    const situacao = notificadoNaJanela ? 'Notificado' : (r.mondayMatch ? 'Notificado fora do período' : 'Não Notificado');
    return { unit: r.unit, empresa: r.empresa, dev: r.dev, situacao };
  });
  const situacaoBadge = s=>{
    if(s==='Notificado') return 'ok';
    if(s==='Notificado fora do período') return 'info';
    return 'fail';
  };

  const totalNotificadas = finalRows.filter(r=>r.situacao==='Notificado').length;
  const aderenciaGeral = flagged.length ? totalNotificadas/flagged.length : null;

  document.getElementById('nejCards').innerHTML = `
    <div class="card"><div class="lbl">Empresas avaliadas</div><div class="val">${results.length}</div></div>
    <div class="card accent"><div class="lbl">Precisam notificar</div><div class="val">${flagged.length}</div>
      <div class="sub"><span class="badge fail">Desvio &lt; ${metaVal}%</span></div></div>
    <div class="card"><div class="lbl">Notificadas</div><div class="val">${totalNotificadas}</div>
      <div class="sub">de ${flagged.length} que precisavam</div></div>
    <div class="card"><div class="lbl">Aderência (notificação)</div><div class="val">${aderenciaGeral!==null? fmtPct(aderenciaGeral) : '—'}</div></div>
    <div class="card"><div class="lbl">Unidades carregadas</div><div class="val">${new Set(results.map(r=>r.unit)).size}</div></div>
  `;

  // per-unit breakdown, so it's clear which unit is behind on notifying
  const unitsPresent0 = Array.from(new Set(results.map(r=>r.unit)));
  const perUnitStats = unitsPresent0.map(u=>{
    const avaliadas = results.filter(r=>r.unit===u).length;
    const precisam = flagged.filter(r=>r.unit===u).length;
    const notificadas = finalRows.filter(r=>r.unit===u && r.situacao==='Notificado').length;
    const aderencia = precisam ? notificadas/precisam : null;
    return { unit:u, avaliadas, precisam, notificadas, aderencia };
  });
  document.getElementById('nejUnitStatsTable').innerHTML = `
    <thead><tr><th>Unidade</th><th>Empresas Avaliadas</th><th>Precisam Notificar</th><th>Notificadas</th><th>Aderência</th></tr></thead>
    <tbody>${perUnitStats.map(s=>`<tr>
      <td>${s.unit}</td><td class="num">${s.avaliadas}</td><td class="num">${s.precisam}</td><td class="num">${s.notificadas}</td>
      <td class="num">${s.aderencia!==null? fmtPct(s.aderencia) : '—'}</td>
    </tr>`).join('') || '<tr><td colspan="5">Sem dados</td></tr>'}</tbody>
  `;

  document.getElementById('nejTable').innerHTML = `
    <thead><tr><th>Unidade</th><th>Empresa</th><th>Desvio</th><th>Situação</th><th>Vínculo Monday</th><th></th></tr></thead>
    <tbody>${(()=>{
      let lastUnit = null;
      return results.map(r=>{
        const flag = r.dev < metaVal;
        const candidates = mondayCandidatesForUnit(r.unit);
        const usingFallback = candidates.length === nejMondayGrouped.length && !nejMondayGrouped.some(g=>unitsMatch(r.unit, g.unidade));
        const mondayOptions = ['<option value="">— Não encontrado —</option>']
          .concat(candidates.map(g=>{
            const gk = g.unidade+'|||'+g.empresa;
            const sel = r.mondayMatch && (r.mondayMatch.unidade+'|||'+r.mondayMatch.empresa)===gk ? 'selected' : '';
            return `<option value="${gk}" ${sel}>${g.empresa} (${g.unidade})</option>`;
          }));
        const matchCell = r.mondayMatch
          ? `<span class="badge ok">${r.mondayAuto?'Auto: ':''}${r.mondayMatch.empresa}</span>`
          : `<span class="badge fail">Não encontrado</span>`;
        let groupHeader = '';
        if(r.unit !== lastUnit){
          lastUnit = r.unit;
          const sdLabel = r.periodLabel ? ` — ${r.periodLabel}` : '';
          groupHeader = `<tr class="total"><td colspan="6">${r.unit}${sdLabel}</td></tr>`;
        }
        return groupHeader + `<tr>
          <td>${r.unit}</td>
          <td><input class="proj-name" style="min-width:160px;" value="${r.empresa}" onchange="setNejEmpresaName('${r.editKey.replace(/'/g,"\\'")}', this.value)"></td>
          <td class="num">${r.dev.toFixed(1).replace('.',',')}%</td>
          <td><span class="badge ${flag?'fail':'ok'}">${flag?'Precisa Notificar':'Não se aplica'}</span></td>
          <td>${matchCell}<br><select style="margin-top:4px; max-width:260px;" onchange="setNejMondayMatch('${r.editKey.replace(/'/g,"\\'")}', this.value)">${mondayOptions.join('')}</select>${usingFallback ? '<div style="font-size:10.5px;color:var(--texto-suave);margin-top:2px;">unidade não identificada no Monday — mostrando todas</div>' : ''}</td>
          <td><button onclick="removeNejCompanyRow('${r.editKey.replace(/'/g,"\\'")}')" style="border:none;background:transparent;color:var(--vermelho);font-weight:800;cursor:pointer;">✕</button></td>
        </tr>`;
      }).join('') || '<tr><td colspan="6">Sem dados</td></tr>';
    })()}</tbody>
  `;

  document.getElementById('nejRemovedTable').innerHTML = `
    <thead><tr><th>Unidade</th><th>Empresa</th><th>Desvio</th><th>Justificativa</th></tr></thead>
    <tbody>${removedRows.map(r=>`<tr>
      <td>${r.unit}</td><td>${r.empresa}</td><td class="num">${r.dev.toFixed(1).replace('.',',')}%</td><td>${r.justificativa || '—'}</td>
    </tr>`).join('') || '<tr><td colspan="4">Nenhuma empresa excluída ainda</td></tr>'}</tbody>
  `;

  // one "Baixar Excel" button per unit, so each can be sent to its team separately
  const unitsPresent = Array.from(new Set(results.map(r=>r.unit)));
  document.getElementById('nejUnitExportButtons').innerHTML = unitsPresent.map(u=>
    `<button class="btn secondary" style="margin:0 8px 8px 0;" onclick="exportNejUnitExcel('${u.replace(/'/g,"\\'")}')">Baixar Excel — ${u}</button>`
  ).join('') + (unitsPresent.length>1 ? `<button class="btn secondary" style="margin:0 8px 8px 0;" onclick="exportNejUnitExcel(null)">Baixar Excel — todas as unidades</button>` : '');

  document.getElementById('nejFinalTable').innerHTML = `
    <thead><tr><th>Unidade</th><th>Empresa</th><th>Desvio</th><th>Situação Final</th></tr></thead>
    <tbody>${(()=>{
      let lastUnit = null;
      return finalRows.map(r=>{
        let groupHeader = '';
        if(r.unit !== lastUnit){
          lastUnit = r.unit;
          groupHeader = `<tr class="total"><td colspan="4">${r.unit}</td></tr>`;
        }
        return groupHeader + `<tr>
          <td>${r.unit}</td><td>${r.empresa}</td><td class="num">${r.dev.toFixed(1).replace('.',',')}%</td>
          <td><span class="badge ${situacaoBadge(r.situacao)}">${r.situacao}</span></td>
        </tr>`;
      }).join('') || '<tr><td colspan="4">Sem empresas precisando notificar</td></tr>';
    })()}</tbody>
  `;

  const finalUnitsPresent = Array.from(new Set(finalRows.map(r=>r.unit)));
  document.getElementById('nejFinalUnitExportButtons').innerHTML = finalUnitsPresent.map(u=>
    `<button class="btn secondary" style="margin:0 8px 8px 0;" onclick="exportNejFinalUnitExcel('${u.replace(/'/g,"\\'")}')">Baixar Excel — ${u}</button>`
  ).join('') + (finalUnitsPresent.length>1 ? `<button class="btn secondary" style="margin:0 8px 8px 0;" onclick="exportNejFinalUnitExcel(null)">Baixar Excel — todas as unidades</button>` : '');

  nejLastData = { meta: metaVal, results, flagged, finalRows, removedRows, unitsCount: new Set(results.map(r=>r.unit)).size };
}

function exportNejFinalUnitExcel(unitName){
  if(!nejLastData) return;
  const rows = unitName ? nejLastData.finalRows.filter(r=>r.unit===unitName) : nejLastData.finalRows;
  if(!rows.length) return;
  const aoa = [['Unidade','Empresa','Desvio %','Situação Final']];
  rows.forEach(r=> aoa.push([r.unit, r.empresa, Number((r.dev/100).toFixed(4)), r.situacao]));
  const ws = XLSX.utils.aoa_to_sheet(aoa);
  ws['!cols'] = [{wch:18},{wch:32},{wch:10},{wch:18}];
  for(let i=1; i<aoa.length; i++){
    const cellRef = XLSX.utils.encode_cell({ r:i, c:2 });
    if(ws[cellRef]) ws[cellRef].z = '0.0%';
  }
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Situacao Final');

  const mondayRows = unitName
    ? nejMondayGrouped.filter(g=> unitsMatch(unitName, g.unidade))
    : nejMondayGrouped;
  const mondayAoa = [['Unidade','Empresa','Data Abertura JUR','Data Escrituração','Situação','Motivo(s)']];
  mondayRows.forEach(g=>{
    const motivos = Array.from(new Set(g.entries.map(e=>e.motivo).filter(Boolean))).join(', ');
    mondayAoa.push([g.unidade, g.empresa, fmtDateBR(g.dataAbertura), fmtDateBR(g.dataEscritura), g.situacao, motivos]);
  });
  const wsMonday = XLSX.utils.aoa_to_sheet(mondayAoa);
  wsMonday['!cols'] = [{wch:18},{wch:34},{wch:16},{wch:16},{wch:14},{wch:40}];
  XLSX.utils.book_append_sheet(wb, wsMonday, 'Empresas Monday');

  const removedForUnit = unitName ? nejLastData.removedRows.filter(r=>r.unit===unitName) : nejLastData.removedRows;
  const removedAoa = [['Unidade','Empresa','Desvio %','Justificativa']];
  removedForUnit.forEach(r=> removedAoa.push([r.unit, r.empresa, Number((r.dev/100).toFixed(4)), r.justificativa || '']));
  const wsRemoved = XLSX.utils.aoa_to_sheet(removedAoa);
  wsRemoved['!cols'] = [{wch:18},{wch:32},{wch:10},{wch:50}];
  for(let i=1;i<removedAoa.length;i++){
    const ref = XLSX.utils.encode_cell({r:i,c:2});
    if(wsRemoved[ref]) wsRemoved[ref].z = '0.0%';
  }
  XLSX.utils.book_append_sheet(wb, wsRemoved, 'Empresas Excluídas');

  const fname = `NEJ_SituacaoFinal_${unitName ? unitName.replace(/[^a-zA-Z0-9]+/g,'_') : 'Todas_Unidades'}_${new Date().toISOString().slice(0,10)}.xlsx`;
  XLSX.writeFile(wb, fname);
}

function setNejEmpresaName(editKey, newName){
  if(!nejEdits[editKey]) nejEdits[editKey] = {};
  nejEdits[editKey].name = newName.trim();
  combineAndRenderNej();
}
function setNejMondayMatch(editKey, mondayKey){
  nejMatchOverrides[editKey] = mondayKey;
  combineAndRenderNej();
}
function removeNejCompanyRow(editKey){
  const justificativa = prompt('Por que essa empresa não precisa ser notificada? (obrigatório)');
  if(justificativa === null) return; // cancelled
  if(!justificativa.trim()){
    alert('Precisa escrever uma justificativa pra excluir a empresa.');
    return;
  }
  if(!nejEdits[editKey]) nejEdits[editKey] = {};
  nejEdits[editKey].removed = true;
  nejEdits[editKey].justificativa = justificativa.trim();
  combineAndRenderNej();
}

function exportNejUnitExcel(unitName){
  if(!nejLastData) return;
  const rows = unitName ? nejLastData.results.filter(r=>r.unit===unitName) : nejLastData.results;
  if(!rows.length) return;

  const header = ['Unidade','Empresa','Previsto (Cota)','Realizado','Desvio %','Precisa Notificar','Vínculo Monday','Situação Final'];
  const finalByKey = new Map(nejLastData.finalRows.map(r=>[r.unit+'|||'+r.empresa, r.situacao]));
  const aoa = [header];
  rows.forEach(r=>{
    const flag = r.dev < nejLastData.meta;
    const situacaoFinal = finalByKey.get(r.unit+'|||'+r.empresa) || (flag ? 'Não Notificado' : 'Não se aplica');
    aoa.push([
      r.unit, r.empresa,
      Number(r.bcws.toFixed(2)), Number(r.bcwp.toFixed(2)),
      Number((r.dev/100).toFixed(4)),
      flag ? 'SIM' : 'não',
      r.mondayMatch ? r.mondayMatch.empresa : '',
      situacaoFinal,
    ]);
  });

  const ws = XLSX.utils.aoa_to_sheet(aoa);
  ws['!cols'] = [{wch:18},{wch:32},{wch:16},{wch:16},{wch:10},{wch:14},{wch:32},{wch:18}];
  // percent formatting on the Desvio % column
  for(let i=1; i<aoa.length; i++){
    const cellRef = XLSX.utils.encode_cell({ r:i, c:4 });
    if(ws[cellRef]) ws[cellRef].z = '0.0%';
  }
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'NEJ');

  // second sheet: Monday companies scoped to the same unit(s), with notification dates
  const mondayRows = unitName
    ? nejMondayGrouped.filter(g=> unitsMatch(unitName, g.unidade))
    : nejMondayGrouped;
  const mondayAoa = [['Unidade','Empresa','Data Abertura JUR','Data Escrituração','Situação','Motivo(s)']];
  mondayRows.forEach(g=>{
    const motivos = Array.from(new Set(g.entries.map(e=>e.motivo).filter(Boolean))).join(', ');
    mondayAoa.push([g.unidade, g.empresa, fmtDateBR(g.dataAbertura), fmtDateBR(g.dataEscritura), g.situacao, motivos]);
  });
  const wsMonday = XLSX.utils.aoa_to_sheet(mondayAoa);
  wsMonday['!cols'] = [{wch:18},{wch:34},{wch:16},{wch:16},{wch:14},{wch:40}];
  XLSX.utils.book_append_sheet(wb, wsMonday, 'Empresas Monday');

  // third sheet: companies excluded from the analysis, with their justification
  const removedForUnit = unitName ? nejLastData.removedRows.filter(r=>r.unit===unitName) : nejLastData.removedRows;
  const removedAoa = [['Unidade','Empresa','Desvio %','Justificativa']];
  removedForUnit.forEach(r=> removedAoa.push([r.unit, r.empresa, Number((r.dev/100).toFixed(4)), r.justificativa || '']));
  const wsRemoved = XLSX.utils.aoa_to_sheet(removedAoa);
  wsRemoved['!cols'] = [{wch:18},{wch:32},{wch:10},{wch:50}];
  for(let i=1;i<removedAoa.length;i++){
    const ref = XLSX.utils.encode_cell({r:i,c:2});
    if(wsRemoved[ref]) wsRemoved[ref].z = '0.0%';
  }
  XLSX.utils.book_append_sheet(wb, wsRemoved, 'Empresas Excluídas');

  const fname = `NEJ_${unitName ? unitName.replace(/[^a-zA-Z0-9]+/g,'_') : 'Todas_Unidades'}_${new Date().toISOString().slice(0,10)}.xlsx`;
  XLSX.writeFile(wb, fname);
}

document.getElementById('nejExportPdf').addEventListener('click', ()=>{
  if(!nejLastData) return;
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit:'pt', format:'a4' });
  const d = nejLastData;
  const today = new Date().toLocaleDateString('pt-BR');

  doc.setFont('helvetica','bold'); doc.setFontSize(16); doc.setTextColor(48,79,126);
  doc.text('NEJ - Consolidado', 40, 44);
  doc.setFont('helvetica','normal'); doc.setFontSize(9); doc.setTextColor(110,110,110);
  doc.text(`Gerado em ${today} · meta de desvio: < ${d.meta}%`, 40, 60);

  const cardData = [
    { lbl:'EMPRESAS AVALIADAS', val: String(d.results.length) },
    { lbl:'PRECISAM NOTIFICAR', val: String(d.flagged.length), accent:true },
    { lbl:'UNIDADES', val: String(d.unitsCount) },
  ];
  const cardY=78, cardH=48, gap=12, marginX=40;
  const cardW = (515-gap*2)/3;
  cardData.forEach((c,i)=>{
    const x = marginX + i*(cardW+gap);
    doc.setDrawColor(228,230,234); doc.setFillColor(255,255,255);
    doc.roundedRect(x, cardY, cardW, cardH, 5, 5, 'FD');
    doc.setFont('helvetica','bold'); doc.setFontSize(7.5); doc.setTextColor(107,114,128);
    doc.text(c.lbl, x+10, cardY+17);
    doc.setFont('helvetica','bold'); doc.setFontSize(14);
    doc.setTextColor(...(c.accent?[192,57,43]:[33,55,88]));
    doc.text(c.val, x+10, cardY+35);
  });

  doc.autoTable({
    startY: cardY+cardH+20,
    head: [['Unidade','Empresa','Cota (BCWS)','Custo Acum. (BCWP)','Desvio','Situação']],
    body: d.results.map(r=>{
      const flag = r.dev < d.meta;
      return [r.unit, r.empresa, fmtCurrency(r.bcws), fmtCurrency(r.bcwp), r.dev.toFixed(1).replace('.',',')+'%', flag?'Precisa Notificar':'Não se aplica'];
    }),
    headStyles:{fillColor:[48,79,126],textColor:255,fontStyle:'bold'},
    styles:{font:'helvetica',fontSize:8,cellPadding:4}, theme:'grid',
    didParseCell:(data)=>{ if(data.section==='body'&&data.column.index===5){ data.cell.styles.textColor = data.cell.raw==='Precisa Notificar'?[192,57,43]:[96,147,70]; data.cell.styles.fontStyle='bold'; } }
  });

  const y2 = doc.lastAutoTable.finalY + 24;
  doc.setFont('helvetica','bold'); doc.setFontSize(12); doc.setTextColor(48,79,126);
  doc.text('Situação Final (empresas que precisam notificar)', 40, y2);
  doc.autoTable({
    startY: y2+10,
    head: [['Unidade','Empresa','Desvio','Situação Final']],
    body: d.finalRows.map(r=>[r.unit, r.empresa, r.dev.toFixed(1).replace('.',',')+'%', r.situacao]),
    headStyles:{fillColor:[48,79,126],textColor:255,fontStyle:'bold'},
    styles:{font:'helvetica',fontSize:8,cellPadding:4}, theme:'grid',
    didParseCell:(data)=>{
      if(data.section==='body'&&data.column.index===3){
        const v = data.cell.raw;
        data.cell.styles.textColor = v==='Notificado' ? [96,147,70] : (v==='Notificado fora do período' ? [0,124,197] : [192,57,43]);
        data.cell.styles.fontStyle='bold';
      }
    }
  });

  doc.save(`NEJ_Consolidado_${new Date().toISOString().slice(0,10)}.pdf`);
});

/* ---------- 5S tab ---------- */
// The raw PPR-5S sheet has no literal column-name headers — columns are positional
// (B=Divisão, C=Área, D=Meta, E=Nota) and the "header" is really just the cell
// containing the word "Meta" next to the audit date. One workbook = one month,
// with one sheet per unit.
function parseFsWorkbookMatrix(sheet){
  const matrix = XLSX.utils.sheet_to_json(sheet, {header:1, defval:null, raw:true});
  let headerRow = -1, auditDate = null, metaCol = -1;
  for(let r=0; r<Math.min(matrix.length, 15); r++){
    const row = matrix[r] || [];
    for(let c=0; c<row.length; c++){
      if(String(row[c]||'').trim().toLowerCase() === 'meta'){
        const next = row[c+1];
        if(next instanceof Date && !isNaN(next)){
          headerRow = r; auditDate = next; metaCol = c; break;
        }
      }
    }
    if(headerRow !== -1) break;
  }
  if(headerRow === -1) return null;
  // columns are always laid out as: ... Divisão | Área | Meta | Nota — relative to
  // wherever "Meta" actually landed, so this doesn't depend on how many leading
  // blank columns the sheet happens to have.
  const divisaoCol = metaCol - 2, areaCol = metaCol - 1, notaCol = metaCol + 1;

  const areas = [];
  let currentDivisao = null;
  for(let r=headerRow+1; r<matrix.length; r++){
    const row = matrix[r] || [];
    const divisaoCell = row[divisaoCol];
    const areaCell = row[areaCol];
    const metaCell = row[metaCol];
    const notaCell = row[notaCol];
    if(divisaoCell !== null && divisaoCell !== undefined && String(divisaoCell).trim() !== ''){
      currentDivisao = String(divisaoCell).trim();
    }
    if(areaCell === null || areaCell === undefined) continue;
    const areaName = String(areaCell).trim();
    if(!areaName) continue;
    if(/^média divisão/i.test(areaName)) continue; // we recompute this ourselves
    const meta = parseFloat(metaCell);
    const nota = parseFloat(notaCell);
    if(isNaN(meta) || isNaN(nota)) continue;
    areas.push({ divisao: currentDivisao, area: areaName, meta, nota });
  }
  if(!areas.length) return null;
  return { auditDate, areas };
}

const fsDrop = document.getElementById('fsDrop');
const fsFile = document.getElementById('fsFile');
const fsFileList = document.getElementById('fsFileList');
const fsProgress = document.getElementById('fsProgress');
const fsError = document.getElementById('fsError');
const fsResults = document.getElementById('fsResults');

let fsEntries = []; // {id, name, units: [{unit, ano, mes, areas:[{divisao,area,meta,nota}]}], error}
let fsEntrySeq = 0;
let fsLastData = null;

fsDrop.addEventListener('click', ()=> fsFile.click());
fsDrop.addEventListener('dragover', e=>{ e.preventDefault(); fsDrop.classList.add('drag'); });
fsDrop.addEventListener('dragleave', ()=> fsDrop.classList.remove('drag'));
fsDrop.addEventListener('drop', e=>{
  e.preventDefault(); fsDrop.classList.remove('drag');
  if(e.dataTransfer.files.length) handleFsFiles(Array.from(e.dataTransfer.files));
});
fsFile.addEventListener('change', e=>{
  if(e.target.files.length) handleFsFiles(Array.from(e.target.files));
  fsFile.value = '';
});
document.getElementById('fsClearAll').addEventListener('click', ()=>{
  fsEntries = [];
  fsResults.style.display = 'none';
  renderFsFileList();
});
document.getElementById('fsRecalc').addEventListener('click', ()=> combineAndRenderFs());
document.getElementById('fsExcludeList').addEventListener('change', ()=> combineAndRenderFs());
document.getElementById('fsDetailUnit').addEventListener('change', ()=> renderFsDetail());
document.getElementById('fsDetailMonth').addEventListener('change', ()=> renderFsDetail());

async function handleFsFiles(files){
  fsError.innerHTML = '';
  for(const file of files){
    const entry = { id: ++fsEntrySeq, name: file.name, units: null, error: null };
    fsEntries.push(entry);
    fsProgress.innerHTML = `<div class="progress-item"><span class="spinner"></span> Lendo ${file.name}…</div>`;
    await new Promise(r=>setTimeout(r,0));
    try{
      const buf = await file.arrayBuffer();
      const wb = XLSX.read(buf, {type:'array', cellDates:true});
      const units = [];
      wb.SheetNames.forEach(sheetName=>{
        const parsed = parseFsWorkbookMatrix(wb.Sheets[sheetName]);
        if(parsed){
          units.push({
            unit: sheetName,
            ano: parsed.auditDate.getFullYear(),
            mes: parsed.auditDate.getMonth(), // 0-based
            areas: parsed.areas,
          });
        }
      });
      if(!units.length){
        entry.error = 'Não encontrei nenhuma aba com o padrão "Meta" + data + Divisão/Área/Nota.';
      } else {
        entry.units = units;
      }
    }catch(err){
      entry.error = err.message;
    }
    renderFsFileList();
    await new Promise(r=>setTimeout(r,0));
  }
  fsProgress.innerHTML = '';
  combineAndRenderFs();
}

function renderFsFileList(){
  if(!fsEntries.length){ fsFileList.innerHTML=''; return; }
  fsFileList.innerHTML = `<div class="file-list">${fsEntries.map(e=>{
    if(e.error) return `<span class="file-pill error">${e.name} · erro: ${e.error} <button onclick="removeFsEntry(${e.id})">✕</button></span>`;
    if(!e.units) return `<span class="file-pill">${e.name} · lendo… <button onclick="removeFsEntry(${e.id})">✕</button></span>`;
    const label = e.units.length ? `${MONTH_PT[e.units[0].mes]}/${e.units[0].ano}` : '';
    return `<span class="file-pill">${e.name} · ${e.units.length} unidade(s) · ${label} <button onclick="removeFsEntry(${e.id})">✕</button></span>`;
  }).join('')}</div>`;
}
function removeFsEntry(id){
  fsEntries = fsEntries.filter(e=>e.id!==id);
  renderFsFileList();
  if(fsEntries.some(e=>e.units)) combineAndRenderFs();
  else { fsResults.style.display='none'; }
}

function aderenciaArea(a){ return Math.min(a.nota/a.meta, 1); }

function combineAndRenderFs(){
  const validEntries = fsEntries.filter(e=>e.units);
  if(!validEntries.length){ fsResults.style.display='none'; return; }
  fsResults.style.display = 'block';

  const excludeList = document.getElementById('fsExcludeList').value
    .split(',').map(s=>s.trim().toUpperCase()).filter(Boolean);
  const meta = parseFloat(document.getElementById('fsMeta').value) || 95;

  // unit -> 'YYYY-MM' -> {areas: [...]}
  const byUnitMonth = new Map();
  validEntries.forEach(e=>{
    e.units.forEach(u=>{
      const key = u.unit+'|||'+u.ano+'-'+String(u.mes+1).padStart(2,'0');
      byUnitMonth.set(key, u);
    });
  });

  const units = Array.from(new Set(Array.from(byUnitMonth.values()).map(u=>u.unit))).sort();
  const monthKeys = Array.from(new Set(Array.from(byUnitMonth.values()).map(u=>u.ano+'-'+String(u.mes+1).padStart(2,'0')))).sort();

  // unit x month adherence (average of area-level adherence)
  const unitMonthAder = new Map(); // 'unit|||YYYY-MM' -> aderência (0-1)
  byUnitMonth.forEach((u, key)=>{
    const avg = u.areas.reduce((s,a)=>s+aderenciaArea(a),0) / u.areas.length;
    unitMonthAder.set(key, avg);
  });

  // GERAL per month = average across non-excluded units that have data that month
  const geralByMonth = new Map();
  monthKeys.forEach(mk=>{
    const vals = units.filter(u=>!excludeList.includes(u.toUpperCase()))
      .map(u=> unitMonthAder.get(u+'|||'+mk))
      .filter(v=>v!==undefined);
    geralByMonth.set(mk, vals.length ? vals.reduce((s,v)=>s+v,0)/vals.length : null);
  });

  const lastMonthKey = monthKeys[monthKeys.length-1];
  const geralLast = geralByMonth.get(lastMonthKey);
  const passaMeta = geralLast!==null && geralLast*100 >= meta;

  document.getElementById('fsCards').innerHTML = `
    <div class="card ${passaMeta?'':'accent'}">
      <div class="lbl">GERAL (${lastMonthKey? MONTH_PT[parseInt(lastMonthKey.split('-')[1])-1]+'/'+lastMonthKey.split('-')[0] : '—'})</div>
      <div class="val">${geralLast!==null? fmtPct(geralLast) : '—'}</div>
      <div class="sub"><span class="badge ${passaMeta?'ok':'fail'}">${geralLast!==null? (passaMeta?'Dentro da meta':'Fora da meta') : 'Sem dados'}</span></div>
    </div>
    <div class="card"><div class="lbl">Unidades carregadas</div><div class="val">${units.length}</div></div>
    <div class="card"><div class="lbl">Meses carregados</div><div class="val">${monthKeys.length}</div></div>
  `;

  // Por unidade e mês table
  const headCols = monthKeys.map(mk=>`<th>${MONTH_PT[parseInt(mk.split('-')[1])-1].slice(0,3)}/${mk.split('-')[0].slice(2)}</th>`).join('');
  const unitRowsHtml = units.map(u=>{
    const excluded = excludeList.includes(u.toUpperCase());
    const cells = monthKeys.map(mk=>{
      const ad = unitMonthAder.get(u+'|||'+mk);
      return `<td class="num">${ad!==undefined? fmtPct(ad) : '—'}</td>`;
    }).join('');
    return `<tr>${excluded?'<td>'+u+' <span class="badge">excluída</span></td>':'<td>'+u+'</td>'}${cells}</tr>`;
  }).join('');
  const geralRowHtml = `<tr class="total"><td>GERAL</td>${monthKeys.map(mk=>{
    const g = geralByMonth.get(mk);
    return `<td class="num">${g!==null? fmtPct(g) : '—'}</td>`;
  }).join('')}</tr>`;
  document.getElementById('fsUnitMonthTable').innerHTML = `
    <thead><tr><th>Unidade</th>${headCols}</tr></thead>
    <tbody>${unitRowsHtml}${geralRowHtml}</tbody>
  `;

  // detail selectors
  const unitSelect = document.getElementById('fsDetailUnit');
  const prevUnit = unitSelect.value;
  unitSelect.innerHTML = units.map(u=>`<option value="${u}">${u}</option>`).join('');
  unitSelect.value = units.includes(prevUnit) ? prevUnit : units[0];

  const monthSelect = document.getElementById('fsDetailMonth');
  const prevMonth = monthSelect.value;
  monthSelect.innerHTML = monthKeys.map(mk=>{
    const [y,m] = mk.split('-');
    return `<option value="${mk}">${MONTH_PT[parseInt(m)-1]}/${y}</option>`;
  }).join('');
  monthSelect.value = monthKeys.includes(prevMonth) ? prevMonth : lastMonthKey;

  fsLastData = { meta, units, monthKeys, unitMonthAder, geralByMonth, excludeList, byUnitMonth };
  renderFsDetail();
}

function renderFsDetail(){
  if(!fsLastData) return;
  const unit = document.getElementById('fsDetailUnit').value;
  const mk = document.getElementById('fsDetailMonth').value;
  const u = fsLastData.byUnitMonth.get(unit+'|||'+mk);
  const table = document.getElementById('fsDetailTable');
  if(!u){ table.innerHTML = ''; return; }

  const byDivisao = new Map();
  u.areas.forEach(a=>{
    if(!byDivisao.has(a.divisao)) byDivisao.set(a.divisao, []);
    byDivisao.get(a.divisao).push(a);
  });

  let rowsHtml = '';
  byDivisao.forEach((areas, divisao)=>{
    areas.forEach(a=>{
      rowsHtml += `<tr><td>${divisao}</td><td>${a.area}</td><td class="num">${a.meta}</td><td class="num">${a.nota}</td><td class="num">${fmtPct(aderenciaArea(a))}</td></tr>`;
    });
    const avg = areas.reduce((s,a)=>s+aderenciaArea(a),0)/areas.length;
    rowsHtml += `<tr class="total"><td colspan="4">Média ${divisao}</td><td class="num">${fmtPct(avg)}</td></tr>`;
  });

  table.innerHTML = `
    <thead><tr><th>Divisão</th><th>Área</th><th>Meta</th><th>Nota</th><th>Aderência</th></tr></thead>
    <tbody>${rowsHtml || '<tr><td colspan="5">Sem dados</td></tr>'}</tbody>
  `;
}

document.getElementById('fsExportPdf').addEventListener('click', ()=>{
  if(!fsLastData) return;
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit:'pt', format:'a4' });
  const d = fsLastData;
  const today = new Date().toLocaleDateString('pt-BR');
  const lastMonthKey = d.monthKeys[d.monthKeys.length-1];
  const geralLast = d.geralByMonth.get(lastMonthKey);

  doc.setFont('helvetica','bold'); doc.setFontSize(16); doc.setTextColor(48,79,126);
  doc.text('5S', 40, 44);
  doc.setFont('helvetica','normal'); doc.setFontSize(9); doc.setTextColor(110,110,110);
  doc.text(`Gerado em ${today} · meta global: ${d.meta}%`, 40, 60);

  doc.setFont('helvetica','bold'); doc.setFontSize(13); doc.setTextColor(33,55,88);
  doc.text(`GERAL (${lastMonthKey? MONTH_PT[parseInt(lastMonthKey.split('-')[1])-1]+'/'+lastMonthKey.split('-')[0] : '—'}): ${geralLast!==null? fmtPct(geralLast) : '—'}`, 40, 82);

  doc.autoTable({
    startY: 96,
    head: [['Unidade', ...d.monthKeys.map(mk=> MONTH_PT[parseInt(mk.split('-')[1])-1].slice(0,3)+'/'+mk.split('-')[0].slice(2))]],
    body: [
      ...d.units.map(u=> [u, ...d.monthKeys.map(mk=>{ const ad=d.unitMonthAder.get(u+'|||'+mk); return ad!==undefined? fmtPct(ad):'—'; })]),
      ['GERAL', ...d.monthKeys.map(mk=>{ const g=d.geralByMonth.get(mk); return g!==null? fmtPct(g):'—'; })],
    ],
    headStyles:{fillColor:[48,79,126],textColor:255,fontStyle:'bold'},
    styles:{font:'helvetica',fontSize:9,cellPadding:5}, theme:'grid',
  });

  doc.save(`5S_${new Date().toISOString().slice(0,10)}.pdf`);
});

/* ---------- Taxa de Desligamento tab ---------- */
const REQUIRED_TXD_COLS = ['unidade','ano','mês','quadro_anterior','quadro_atual','qtd_demitidos'];

const txdDrop = document.getElementById('txdDrop');
const txdFile = document.getElementById('txdFile');
const txdFileList = document.getElementById('txdFileList');
const txdProgress = document.getElementById('txdProgress');
const txdError = document.getElementById('txdError');
const txdResults = document.getElementById('txdResults');

let txdEntries = []; // uploaded files: {id, name, rows, error}
let txdManualRows = []; // rows added by hand on this screen
let txdLastData = null;

(function initTxdMonthSelect(){
  const sel = document.getElementById('txdNewMes');
  sel.innerHTML = MONTH_PT.map((m,i)=>`<option value="${i+1}">${m}</option>`).join('');
})();

txdDrop.addEventListener('click', ()=> txdFile.click());
txdDrop.addEventListener('dragover', e=>{ e.preventDefault(); txdDrop.classList.add('drag'); });
txdDrop.addEventListener('dragleave', ()=> txdDrop.classList.remove('drag'));
txdDrop.addEventListener('drop', e=>{
  e.preventDefault(); txdDrop.classList.remove('drag');
  if(e.dataTransfer.files.length) handleTxdFiles(Array.from(e.dataTransfer.files));
});
txdFile.addEventListener('change', e=>{
  if(e.target.files.length) handleTxdFiles(Array.from(e.target.files));
  txdFile.value = '';
});
document.getElementById('txdClearAll').addEventListener('click', ()=>{
  txdEntries = []; txdManualRows = [];
  txdResults.style.display = 'none';
  renderTxdFileList();
});
document.getElementById('txdRecalc').addEventListener('click', ()=> combineAndRenderTxd());

document.getElementById('txdAddRow').addEventListener('click', ()=>{
  const unidade = document.getElementById('txdNewUnidade').value.trim();
  const ano = parseInt(document.getElementById('txdNewAno').value);
  const mes = parseInt(document.getElementById('txdNewMes').value);
  const qa = parseFloat(document.getElementById('txdNewQA').value);
  const qat = parseFloat(document.getElementById('txdNewQAT').value);
  const dem = parseFloat(document.getElementById('txdNewDem').value);
  const metaPct = parseFloat(document.getElementById('txdNewMeta').value);
  if(!unidade || isNaN(ano) || isNaN(mes) || isNaN(qa) || isNaN(qat) || isNaN(dem) || isNaN(metaPct)){
    txdError.innerHTML = `<div class="error-box">Preenche todos os campos antes de adicionar.</div>`;
    return;
  }
  txdError.innerHTML = '';
  // manual entry overwrites any existing row for the same unidade+ano+mês
  txdManualRows = txdManualRows.filter(r=> !(r.unidade.toUpperCase()===unidade.toUpperCase() && r.ano===ano && r.mes===mes));
  txdManualRows.push({ unidade, ano, mes, qa, qat, dem, meta: metaPct });
  document.getElementById('txdNewQA').value = '';
  document.getElementById('txdNewQAT').value = '';
  document.getElementById('txdNewDem').value = '';
  combineAndRenderTxd();
});

async function handleTxdFiles(files){
  txdError.innerHTML = '';
  for(const file of files){
    const entry = { id: Date.now()+Math.random(), name: file.name, rows: null, setorRows: null, error: null };
    txdEntries.push(entry);
    txdProgress.innerHTML = `<div class="progress-item"><span class="spinner"></span> Lendo ${file.name}…</div>`;
    await new Promise(r=>setTimeout(r,0));
    try{
      const wb = await readWorkbookAllSheets(file);
      const matrix = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], {header:1, defval:null, raw:true});
      const rawRows = parseWithHeaderDetection(matrix, REQUIRED_TXD_COLS);
      if(!rawRows){
        entry.error = 'Não encontrei as colunas Unidade, Ano, Mês, Quadro Anterior, Quadro Atual e Qtd Demitidos.';
      } else {
        const sampleKeys = rawRows.length ? Object.keys(rawRows[0]) : [];
        const metaKey = sampleKeys.find(k=> k.includes('meta')) || 'meta';
        entry.rows = rawRows.map(r=>({
          unidade: String(r['unidade']||'').trim(),
          ano: parseInt(r['ano']),
          mes: parseInt(r['mês']),
          qa: parseFloat(r['quadro_anterior']),
          qat: parseFloat(r['quadro_atual']),
          dem: parseFloat(r['qtd_demitidos']),
          meta: parseFloat(r[metaKey]) || 2,
        })).filter(r=> r.unidade && !isNaN(r.ano) && !isNaN(r.mes) && !isNaN(r.qa) && !isNaN(r.qat) && !isNaN(r.dem));
        if(!entry.rows.length) entry.error = 'Nenhuma linha válida encontrada.';
      }
      // optional second sheet with per-departure setor/cargo detail
      const setorSheetName = wb.SheetNames.find(n=> n.toLowerCase().includes('setor'));
      if(setorSheetName){
        const setorMatrix = XLSX.utils.sheet_to_json(wb.Sheets[setorSheetName], {header:1, defval:null, raw:true});
        const setorRaw = parseWithHeaderDetection(setorMatrix, ['unidade','ano','mês','setor_/_objeto_de_custo','qtd']);
        if(setorRaw){
          const sk = setorRaw.length ? Object.keys(setorRaw[0]) : [];
          const setorKey = sk.find(k=> k.includes('setor')) || 'setor';
          entry.setorRows = setorRaw.map(r=>({
            unidade: String(r['unidade']||'').trim(),
            ano: parseInt(r['ano']),
            mes: parseInt(r['mês']),
            setor: String(r[setorKey]||'').trim(),
            qtd: parseFloat(r['qtd']) || 0,
          })).filter(r=> r.unidade && r.setor && !isNaN(r.ano) && !isNaN(r.mes));
        }
      }
    }catch(err){
      entry.error = err.message;
    }
    renderTxdFileList();
    await new Promise(r=>setTimeout(r,0));
  }
  txdProgress.innerHTML = '';
  combineAndRenderTxd();
}

function renderTxdFileList(){
  if(!txdEntries.length){ txdFileList.innerHTML=''; return; }
  txdFileList.innerHTML = `<div class="file-list">${txdEntries.map(e=>{
    if(e.error) return `<span class="file-pill error">${e.name} · erro: ${e.error} <button onclick="removeTxdEntry('${e.id}')">✕</button></span>`;
    if(!e.rows) return `<span class="file-pill">${e.name} · lendo… <button onclick="removeTxdEntry('${e.id}')">✕</button></span>`;
    return `<span class="file-pill">${e.name} · ${e.rows.length.toLocaleString('pt-BR')} linhas <button onclick="removeTxdEntry('${e.id}')">✕</button></span>`;
  }).join('')}</div>`;
}
function removeTxdEntry(id){
  txdEntries = txdEntries.filter(e=>String(e.id)!==String(id));
  renderTxdFileList();
  combineAndRenderTxd();
}

function taxaCalc(r){
  const taxa = r.qa > 0 ? (r.dem / r.qa) : 0;
  const aderencia = taxa > 0 ? ((r.meta/100) / taxa) : 0; // mirrors the original sheet's IFERROR(Meta/Taxa,0)
  const ok = (taxa*100) <= r.meta;
  return { taxa, aderencia, ok };
}

function combineAndRenderTxd(){
  // uploaded rows first, manual entries overwrite same unidade+ano+mês on top
  const all = new Map();
  txdEntries.forEach(e=>{ if(e.rows) e.rows.forEach(r=>{
    all.set(r.unidade.toUpperCase()+'|||'+r.ano+'-'+r.mes, r);
  }); });
  txdManualRows.forEach(r=>{
    all.set(r.unidade.toUpperCase()+'|||'+r.ano+'-'+r.mes, r);
  });

  if(!all.size){ txdResults.style.display='none'; return; }
  txdResults.style.display = 'block';

  const rows = Array.from(all.values());
  const units = Array.from(new Set(rows.map(r=>r.unidade))).sort();
  const monthKeys = Array.from(new Set(rows.map(r=>r.ano+'-'+String(r.mes).padStart(2,'0')))).sort();
  const byUnitMonth = new Map();
  rows.forEach(r=> byUnitMonth.set(r.unidade.toUpperCase()+'|||'+r.ano+'-'+String(r.mes).padStart(2,'0'), r));

  // cards: most recent month, across units that have data that month
  const lastKey = monthKeys[monthKeys.length-1];
  const lastRows = units.map(u=> byUnitMonth.get(u.toUpperCase()+'|||'+lastKey)).filter(Boolean);
  const totalDem = lastRows.reduce((s,r)=>s+r.dem,0);
  const totalQa = lastRows.reduce((s,r)=>s+r.qa,0);
  const taxaGeral = totalQa ? totalDem/totalQa : 0;
  const unitsOk = lastRows.filter(r=> taxaCalc(r).ok).length;

  document.getElementById('txdCards').innerHTML = `
    <div class="card"><div class="lbl">Taxa geral (${lastKey? MONTH_PT[parseInt(lastKey.split('-')[1])-1]+'/'+lastKey.split('-')[0] : '—'})</div><div class="val">${fmtPct(taxaGeral)}</div></div>
    <div class="card"><div class="lbl">Unidades dentro da meta</div><div class="val">${unitsOk}/${lastRows.length}</div></div>
    <div class="card"><div class="lbl">Total demitidos (mês)</div><div class="val">${totalDem}</div></div>
    <div class="card"><div class="lbl">Meses carregados</div><div class="val">${monthKeys.length}</div></div>
  `;

  const headCols = monthKeys.map(mk=>`<th>${MONTH_PT[parseInt(mk.split('-')[1])-1].slice(0,3)}/${mk.split('-')[0].slice(2)}</th>`).join('');
  const bodyRows = units.map(u=>{
    const cells = monthKeys.map(mk=>{
      const r = byUnitMonth.get(u.toUpperCase()+'|||'+mk);
      if(!r) return '<td class="num">—</td>';
      const { taxa, ok } = taxaCalc(r);
      return `<td class="num">${fmtPct(taxa)} <span class="badge ${ok?'ok':'fail'}" style="font-size:10px;">${ok?'OK':'Fora'}</span></td>`;
    }).join('');
    return `<tr><td>${u}</td>${cells}</tr>`;
  }).join('');
  document.getElementById('txdTable').innerHTML = `
    <thead><tr><th>Unidade</th>${headCols}</tr></thead>
    <tbody>${bodyRows}</tbody>
  `;

  // Consolidado mensal — sum across all loaded units, per month
  const metaConsolidada = 2; // matches the original sheet's fixed "Meta consolidada: 2,0%"
  const consolidadoRows = monthKeys.map(mk=>{
    const rs = units.map(u=> byUnitMonth.get(u.toUpperCase()+'|||'+mk)).filter(Boolean);
    const totQa = rs.reduce((s,r)=>s+r.qa,0);
    const totDem = rs.reduce((s,r)=>s+r.dem,0);
    const taxa = totQa ? totDem/totQa : 0;
    const aderencia = taxa>0 ? (metaConsolidada/100)/taxa : 0;
    const diff = metaConsolidada - taxa*100;
    const ok = (taxa*100) <= metaConsolidada;
    return { mk, totQa, totDem, taxa, aderencia, diff, ok };
  });
  document.getElementById('txdConsolidadoTable').innerHTML = `
    <thead><tr><th>Mês</th><th>Total Quad. Anterior</th><th>Total Demitidos</th><th>Taxa Consolidada</th><th>Meta</th><th>Aderência</th><th>Diferença (p.p.)</th><th>Status</th></tr></thead>
    <tbody>${consolidadoRows.map(c=>`<tr>
      <td>${MONTH_PT[parseInt(c.mk.split('-')[1])-1]}/${c.mk.split('-')[0]}</td>
      <td class="num">${c.totQa}</td><td class="num">${c.totDem}</td>
      <td class="num">${fmtPct(c.taxa)}</td><td class="num">${metaConsolidada}%</td>
      <td class="num">${fmtPct(c.aderencia)}</td><td class="num">${c.diff.toFixed(2)} p.p.</td>
      <td><span class="badge ${c.ok?'ok':'fail'}">${c.ok?'Dentro da Meta':'Acima da Meta'}</span></td>
    </tr>`).join('') || '<tr><td colspan="8">Sem dados</td></tr>'}</tbody>
  `;

  // Ranking de aderência por unidade — average of the months actually loaded for that unit
  const rankingRows = units.map(u=>{
    const rs = monthKeys.map(mk=> byUnitMonth.get(u.toUpperCase()+'|||'+mk)).filter(Boolean);
    const calcs = rs.map(taxaCalc);
    const mediaTaxa = calcs.length ? calcs.reduce((s,c)=>s+c.taxa,0)/calcs.length : 0;
    const mediaAderencia = calcs.length ? calcs.reduce((s,c)=>s+c.aderencia,0)/calcs.length : 0;
    const avaliacao = mediaAderencia >= 1 ? '🟢 Meta Superada' : '🔴 Crítico';
    return { unidade: u, mediaTaxa, mediaAderencia, avaliacao };
  }).sort((a,b)=> b.mediaAderencia - a.mediaAderencia);
  document.getElementById('txdRankingTable').innerHTML = `
    <thead><tr><th>Unidade</th><th>Média Taxa</th><th>Aderência Média</th><th>Avaliação</th></tr></thead>
    <tbody>${rankingRows.map(r=>`<tr>
      <td>${r.unidade}</td><td class="num">${fmtPct(r.mediaTaxa)}</td><td class="num">${fmtPct(r.mediaAderencia)}</td>
      <td>${r.avaliacao}</td>
    </tr>`).join('') || '<tr><td colspan="4">Sem dados</td></tr>'}</tbody>
  `;

  // Disciplinas mais impactadas — pivot Setor x Unidade, from the optional "Desligamentos por Setor" sheet(s)
  const setorRowsAll = [];
  txdEntries.forEach(e=>{ if(e.setorRows) setorRowsAll.push(...e.setorRows); });
  if(setorRowsAll.length){
    const setores = Array.from(new Set(setorRowsAll.map(r=>r.setor))).sort();
    const setorUnits = Array.from(new Set(setorRowsAll.map(r=>r.unidade))).sort();
    const grid = new Map(); // setor|||unidade -> qtd
    setorRowsAll.forEach(r=>{
      const k = r.setor+'|||'+r.unidade;
      grid.set(k, (grid.get(k)||0) + r.qtd);
    });
    const unitTotals = setorUnits.map(u=> setorRowsAll.filter(r=>r.unidade===u).reduce((s,r)=>s+r.qtd,0));
    const grandTotal = setorRowsAll.reduce((s,r)=>s+r.qtd,0);
    document.getElementById('txdSetorTable').innerHTML = `
      <thead><tr><th>Setor / Disciplina</th>${setorUnits.map(u=>`<th>${u}</th>`).join('')}<th>Total</th></tr></thead>
      <tbody>
        ${setores.map(s=>{
          const cells = setorUnits.map(u=> `<td class="num">${grid.get(s+'|||'+u) || 0}</td>`).join('');
          const total = setorUnits.reduce((sum,u)=> sum + (grid.get(s+'|||'+u)||0), 0);
          return `<tr><td>${s}</td>${cells}<td class="num">${total}</td></tr>`;
        }).join('')}
        <tr class="total"><td>TOTAL GERAL</td>${unitTotals.map(t=>`<td class="num">${t}</td>`).join('')}<td class="num">${grandTotal}</td></tr>
      </tbody>
    `;
  } else {
    document.getElementById('txdSetorTable').innerHTML = `<thead><tr><th>Setor / Disciplina</th></tr></thead><tbody><tr><td>Sem detalhe de setor carregado ainda — suba a planilha com a aba "Desligamentos por Setor".</td></tr></tbody>`;
  }

  txdLastData = { units, monthKeys, byUnitMonth, taxaGeral, lastKey, consolidadoRows, rankingRows, metaConsolidada };
}

document.getElementById('txdExportExcel').addEventListener('click', ()=>{
  if(!txdLastData) return;
  const d = txdLastData;
  const aoa = [['Unidade','Ano','Mês','Quadro Anterior','Quadro Atual','Qtd Demitidos','Meta (%)','Taxa (%)','Aderência (%)','Status']];
  d.monthKeys.forEach(mk=>{
    const [y,m] = mk.split('-');
    d.units.forEach(u=>{
      const r = d.byUnitMonth.get(u.toUpperCase()+'|||'+mk);
      if(!r) return;
      const { taxa, aderencia, ok } = taxaCalc(r);
      aoa.push([u, parseInt(y), parseInt(m), r.qa, r.qat, r.dem, r.meta, Number((taxa).toFixed(4)), Number((aderencia).toFixed(4)), ok?'OK':'Fora da meta']);
    });
  });
  const ws = XLSX.utils.aoa_to_sheet(aoa);
  ws['!cols'] = [{wch:16},{wch:6},{wch:6},{wch:14},{wch:12},{wch:14},{wch:10},{wch:10},{wch:12},{wch:12}];
  for(let i=1;i<aoa.length;i++){
    ['H','I'].forEach(col=>{
      const ref = col+(i+1);
      if(ws[ref]) ws[ref].z = '0.0%';
    });
  }
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Taxa de Desligamento');
  XLSX.writeFile(wb, `Taxa_Desligamento_${new Date().toISOString().slice(0,10)}.xlsx`);
});

document.getElementById('txdExportPdf').addEventListener('click', ()=>{
  if(!txdLastData) return;
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit:'pt', format:'a4' });
  const d = txdLastData;
  const today = new Date().toLocaleDateString('pt-BR');

  doc.setFont('helvetica','bold'); doc.setFontSize(16); doc.setTextColor(48,79,126);
  doc.text('Taxa de Desligamento', 40, 44);
  doc.setFont('helvetica','normal'); doc.setFontSize(9); doc.setTextColor(110,110,110);
  doc.text(`Gerado em ${today}`, 40, 60);

  doc.autoTable({
    startY: 76,
    head: [['Unidade', ...d.monthKeys.map(mk=> MONTH_PT[parseInt(mk.split('-')[1])-1].slice(0,3)+'/'+mk.split('-')[0].slice(2))]],
    body: d.units.map(u=>[u, ...d.monthKeys.map(mk=>{
      const r = d.byUnitMonth.get(u.toUpperCase()+'|||'+mk);
      if(!r) return '—';
      const { taxa, ok } = taxaCalc(r);
      return fmtPct(taxa) + (ok?' (OK)':' (Fora)');
    })]),
    headStyles:{fillColor:[48,79,126],textColor:255,fontStyle:'bold'},
    styles:{font:'helvetica',fontSize:8,cellPadding:4}, theme:'grid',
  });

  doc.save(`Taxa_Desligamento_${new Date().toISOString().slice(0,10)}.pdf`);
});

/* ---------- 2026 — Scorecard consolidado ---------- */
const SC_INDICATORS = [
  { key:'rdo', label:'Aprovação RDO', peso:15.00, meta:76, direction:'higher', unit:'%', tab:'rdo' },
  { key:'cronograma', label:'Aderência Cronograma', peso:15.60, meta:98, direction:'higher', unit:'%', tab:'idp-disciplinas' },
  { key:'idc', label:'Índice de Desempenho de Custo', peso:8.63, meta:80, direction:'higher', unit:'%', tab:'idc-custos' },
  { key:'rnc', label:'RNC', peso:5.75, meta:15, direction:'lower', unit:'dias', tab:'rnc' },
  { key:'treinamentos', label:'Treinamentos (Itiel)', peso:15.00, meta:90, direction:'higher', unit:'%', tab:'treinamentos' },
  { key:'nej', label:'NEJ', peso:6.57, meta:80, direction:'higher', unit:'%', tab:'nej-consolidado' },
  { key:'taxa_desligamento', label:'Taxa de Desligamento', peso:7.70, meta:2, direction:'lower', unit:'%', tab:'taxa-desligamento' },
  { key:'5s', label:'5S', peso:13.66, meta:95, direction:'higher', unit:'%', tab:'5s' },
  { key:'taxa_acidentes', label:'Taxa de Acidentes', peso:12.09, meta:7.5, direction:'lower', unit:'', tab:null },
];

let scData = {}; // 'YYYY-MM' -> { indicatorKey: rawValue }

function scCurrentKey(){
  const m = document.getElementById('scMonthSelect').value;
  const y = document.getElementById('scYear').value;
  return y+'-'+String(m).padStart(2,'0');
}

function pullIndicatorValue(key){
  try{
    switch(key){
      case 'rdo':
        return (rdoLastData && rdoLastData.totalEmitidos) ? (rdoLastData.totalAprovados/rdoLastData.totalEmitidos*100) : null;
      case 'cronograma':
        return idpLastData ? idpLastData.aderGeral*100 : null;
      case 'idc':
        return idcLastData ? idcLastData.adGeral*100 : null;
      case 'rnc': {
        if(!rncLastData || !rncLastData.monthKeys) return null;
        const k = scCurrentKey();
        const [y,m] = k.split('-');
        const label = MONTH_PT[parseInt(m)-1]+'/'+y;
        const entry = rncLastData.monthKeys.find(mk=> mk.label === label);
        return (entry && entry.dias!==null && entry.dias!==undefined) ? entry.dias : null;
      }
      case 'treinamentos':
        return (trnLastData && trnLastData.itiel && trnLastData.itiel.total) ? (trnLastData.itiel.noPrazo/trnLastData.itiel.total*100) : null;
      case 'nej': {
        if(!nejLastData || !nejLastData.finalRows || !nejLastData.finalRows.length) return null;
        const notif = nejLastData.finalRows.filter(r=>r.situacao==='Notificado').length;
        return notif/nejLastData.finalRows.length*100;
      }
      case 'taxa_desligamento': {
        if(!txdLastData || !txdLastData.consolidadoRows || !txdLastData.consolidadoRows.length) return null;
        const last = txdLastData.consolidadoRows[txdLastData.consolidadoRows.length-1];
        return last.taxa*100;
      }
      case '5s': {
        if(!fsLastData || !fsLastData.monthKeys.length) return null;
        const lastMonth = fsLastData.monthKeys[fsLastData.monthKeys.length-1];
        const g = fsLastData.geralByMonth.get(lastMonth);
        return (g!==null && g!==undefined) ? g*100 : null;
      }
      default: return null;
    }
  }catch(e){ return null; }
}

(function initScMonthSelect(){
  const sel = document.getElementById('scMonthSelect');
  sel.innerHTML = MONTH_PT.map((m,i)=>`<option value="${i+1}">${m}</option>`).join('');
  sel.value = new Date().getMonth()+1;
})();

document.getElementById('scMonthSelect').addEventListener('change', renderScorecard);
document.getElementById('scYear').addEventListener('change', renderScorecard);
document.getElementById('scRecalc').addEventListener('click', renderScorecard);

function pnlLabelToKey(label){
  // "Junho/2026" -> "2026-06"
  const [mesNome, ano] = String(label||'').split('/');
  const mi = MONTH_PT.findIndex(m => m.toLowerCase() === String(mesNome||'').trim().toLowerCase());
  if(mi===-1 || !ano) return null;
  return ano.trim()+'-'+String(mi+1).padStart(2,'0');
}

// Pra quem tem a série mensal disponível na própria aba (não só o mês selecionado na
// tela), isso devolve TODOS os meses de uma vez: { 'YYYY-MM': valor, ... }. Pra quem não
// tem esse histórico guardado (Treinamentos, NEJ, Taxa de Acidentes), devolve {} — nesse
// caso só dá pra puxar mês a mês mesmo, com o botão normal.
function pullIndicatorAllMonths(key){
  const out = {};
  try{
    switch(key){
      case 'rdo':
        if(rdoLastData) rdoLastData.months.forEach(m=>{
          const k = pnlLabelToKey(m.label);
          if(k && m.emitidos) out[k] = m.aprovados/m.emitidos*100;
        });
        break;
      case 'rnc':
        if(rncLastData) rncLastData.monthKeys.forEach(m=>{
          const k = pnlLabelToKey(m.label);
          if(k && m.dias!==null && m.dias!==undefined) out[k] = m.dias;
        });
        break;
      case 'taxa_desligamento':
        if(txdLastData) txdLastData.consolidadoRows.forEach(c=>{ out[c.mk] = c.taxa*100; });
        break;
      case '5s':
        if(fsLastData) fsLastData.monthKeys.forEach(mk=>{
          const g = fsLastData.geralByMonth.get(mk);
          if(g!==null && g!==undefined) out[mk] = g*100;
        });
        break;
      case 'idc':
        if(idcLastData){
          const byMonth = new Map();
          idcLastData.rows.forEach(r=>{
            (r.series||[]).forEach(mp=>{
              const k = mp.year+'-'+String(mp.monthIndex+1).padStart(2,'0');
              if(!byMonth.has(k)) byMonth.set(k, {previsto:0, real:0});
              const acc = byMonth.get(k); acc.previsto += mp.previstoMensal; acc.real += mp.realMensal;
            });
          });
          byMonth.forEach((v,k)=>{ if(v.previsto) out[k] = v.real/v.previsto*100; });
        }
        break;
      case 'cronograma':
        if(idpLastData){
          const byMonth = new Map();
          idpLastData.byUnitDetail.forEach(discMap=>{
            discMap.forEach(monthMap=>{
              monthMap.forEach((v,mi)=>{
                const k = idpLastData.selectedYear+'-'+String(mi+1).padStart(2,'0');
                if(!byMonth.has(k)) byMonth.set(k, {lb:0, real:0});
                const acc = byMonth.get(k); acc.lb += v.lb; acc.real += v.real;
              });
            });
          });
          byMonth.forEach((v,k)=>{ if(v.lb) out[k] = v.real/v.lb*100; });
        }
        break;
      // treinamentos, nej, taxa_acidentes: sem histórico mensal disponível na aba —
      // fica de fora de propósito, use "Puxar da aba" (mês a mês) pra esses.
    }
  }catch(e){}
  return out;
}

function scPullAll(key){
  const monthly = pullIndicatorAllMonths(key);
  const keys = Object.keys(monthly);
  if(!keys.length){
    alert('Essa aba não guarda um histórico mês a mês pra puxar de uma vez — use "Puxar" normal, mês a mês.');
    return;
  }
  keys.forEach(k=>{
    if(!scData[k]) scData[k] = {};
    scData[k][key] = monthly[k];
  });
  renderScorecard();
  alert('Puxados '+keys.length+' mês(es) de uma vez: '+keys.map(k=>MONTH_PT[parseInt(k.split('-')[1])-1]+'/'+k.split('-')[0]).join(', '));
}

function scPull(key){
  const val = pullIndicatorValue(key);
  if(val===null){
    alert('Não encontrei dado carregado nessa aba ainda. Abra a aba, carregue os dados, e tente puxar de novo.');
    return;
  }
  const k = scCurrentKey();
  if(!scData[k]) scData[k] = {};
  scData[k][key] = val;
  renderScorecard();
}
function scSetManual(key, value){
  const k = scCurrentKey();
  if(!scData[k]) scData[k] = {};
  const v = parseFloat(value);
  scData[k][key] = isNaN(v) ? undefined : v;
  renderScorecard();
}

function scIndicatorResult(indicator, value){
  if(value===null || value===undefined || isNaN(value)) return { pass:false, pontos:0, hasValue:false };
  const pass = indicator.direction==='higher' ? value >= indicator.meta : value <= indicator.meta;
  return { pass, pontos: pass ? indicator.peso : 0, hasValue:true };
}

function renderScorecard(){
  const k = scCurrentKey();
  const snapshot = scData[k] || {};

  let totalPontos = 0, totalPeso = 0;
  const rowsHtml = SC_INDICATORS.map(ind=>{
    const value = snapshot[ind.key];
    const { pass, pontos, hasValue } = scIndicatorResult(ind, value);
    totalPontos += pontos; totalPeso += ind.peso;
    const displayValue = hasValue ? (ind.unit==='%' ? value.toFixed(1) : value.toFixed(1)) : '';
    const pullBtn = ind.tab ? `<button class="btn secondary" style="padding:5px 10px;font-size:11px;" onclick="scPull('${ind.key}')">Puxar</button>` : '';
    const pullAllBtn = ind.tab ? `<button class="btn secondary" style="padding:5px 10px;font-size:11px;margin-left:4px;" onclick="scPullAll('${ind.key}')" title="Traz todos os meses que a aba já tiver, de uma vez">Puxar todos os meses</button>` : '';
    return `<tr>
      <td>${ind.label}</td>
      <td class="num">${ind.peso.toFixed(2)}%</td>
      <td class="num">${ind.meta}${ind.unit}</td>
      <td><input type="number" step="0.1" style="width:90px;" value="${displayValue}" onchange="scSetManual('${ind.key}', this.value)"> ${ind.unit}</td>
      <td>${pullBtn}${pullAllBtn}</td>
      <td class="num">${hasValue ? pontos.toFixed(2)+'%' : '—'}</td>
      <td>${hasValue ? `<span class="badge ${pass?'ok':'fail'}">${pass?'Dentro da meta':'Fora da meta'}</span>` : '<span class="badge">Sem dado</span>'}</td>
    </tr>`;
  }).join('');

  document.getElementById('scTable').innerHTML = `
    <thead><tr><th>Indicador</th><th>Peso</th><th>Meta</th><th>Resultado</th><th></th><th>Pontos</th><th>Situação</th></tr></thead>
    <tbody>${rowsHtml}
      <tr class="total"><td colspan="5">TOTAL</td><td class="num">${totalPontos.toFixed(2)}%</td><td></td></tr>
    </tbody>
  `;

  const passaGeral = totalPontos >= 80; // informal "healthy scorecard" threshold for the card color
  document.getElementById('scCards').innerHTML = `
    <div class="card ${passaGeral?'':'accent'}">
      <div class="lbl">Pontuação total (${MONTH_PT[parseInt(k.split('-')[1])-1]}/${k.split('-')[0]})</div>
      <div class="val">${totalPontos.toFixed(1)}%</div>
    </div>
    <div class="card"><div class="lbl">Indicadores com dado</div><div class="val">${SC_INDICATORS.filter(i=> snapshot[i.key]!==undefined).length}/${SC_INDICATORS.length}</div></div>
    <div class="card"><div class="lbl">Dentro da meta</div><div class="val">${SC_INDICATORS.filter(i=> scIndicatorResult(i, snapshot[i.key]).pass).length}/${SC_INDICATORS.length}</div></div>
  `;

  const monthKeysWithData = Object.keys(scData).sort();
  document.getElementById('scHistoryTable').innerHTML = `
    <thead><tr>
      <th>Indicador</th><th>Meta</th><th>Peso</th>
      ${monthKeysWithData.map(mk=>`<th>${MONTH_PT[parseInt(mk.split('-')[1])-1].slice(0,3)}/${mk.split('-')[0].slice(2)}</th>`).join('')}
      <th>Parcial</th><th>Consolidado</th>
    </tr></thead>
    <tbody>${SC_INDICATORS.map(ind=>{
      const cells = monthKeysWithData.map(mk=>{
        const v = (scData[mk]||{})[ind.key];
        const { pass, hasValue } = scIndicatorResult(ind, v);
        const icon = !hasValue ? '—' : (pass ? '✅' : '🔴');
        const title = hasValue ? `${v.toFixed(1)}${ind.unit}` : 'sem dado';
        return `<td class="num" style="cursor:pointer;" title="${title}" onclick="scEditHistoryCell('${ind.key}','${mk}')">${icon}</td>`;
      }).join('');
      const values = monthKeysWithData.map(mk=>(scData[mk]||{})[ind.key]).filter(v=>v!==undefined);
      const parcial = values.length ? values.reduce((s,v)=>s+v,0)/values.length : null;
      const parcialPass = parcial!==null ? scIndicatorResult(ind, parcial).pass : false;
      return `<tr>
        <td>${ind.label}</td><td class="num">${ind.meta}${ind.unit}</td><td class="num">${ind.peso.toFixed(2)}%</td>
        ${cells}
        <td class="num">${parcial!==null ? parcial.toFixed(1)+ind.unit : '—'}</td>
        <td>${parcial!==null ? `<span class="badge ${parcialPass?'ok':'fail'}">${parcialPass?'OK':'Atenção'}</span>` : '—'}</td>
      </tr>`;
    }).join('') || ''}
    ${!monthKeysWithData.length ? `<tr><td colspan="${3+2}">Nenhum mês salvo ainda</td></tr>` : ''}
    </tbody>
  `;
}
function scEditHistoryCell(indicatorKey, monthKey){
  const ind = SC_INDICATORS.find(i=>i.key===indicatorKey);
  const current = (scData[monthKey]||{})[indicatorKey];
  const input = prompt(`${ind.label} — ${MONTH_PT[parseInt(monthKey.split('-')[1])-1]}/${monthKey.split('-')[0]}\nMeta: ${ind.meta}${ind.unit}\n\nDigite o resultado (deixe em branco pra apagar):`, current!==undefined ? current : '');
  if(input === null) return; // cancelled
  if(!scData[monthKey]) scData[monthKey] = {};
  if(input.trim() === ''){
    delete scData[monthKey][indicatorKey];
  } else {
    const v = parseFloat(input.replace(',','.'));
    if(!isNaN(v)) scData[monthKey][indicatorKey] = v;
  }
  renderScorecard();
}
renderScorecard();

document.getElementById('scExportExcel').addEventListener('click', ()=>{
  const monthKeysWithData = Object.keys(scData).sort();
  if(!monthKeysWithData.length) return;
  const aoa = [['Mês', ...SC_INDICATORS.map(i=>i.label), 'Total']];
  monthKeysWithData.forEach(mk=>{
    const snap = scData[mk];
    let tot = 0;
    const cells = SC_INDICATORS.map(ind=>{
      const v = snap[ind.key];
      const { pontos, hasValue } = scIndicatorResult(ind, v);
      tot += pontos;
      return hasValue ? Number(v.toFixed(2)) : '';
    });
    aoa.push([MONTH_PT[parseInt(mk.split('-')[1])-1]+'/'+mk.split('-')[0], ...cells, Number(tot.toFixed(2))]);
  });
  const ws = XLSX.utils.aoa_to_sheet(aoa);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, '2026');
  XLSX.writeFile(wb, `Scorecard_2026_${new Date().toISOString().slice(0,10)}.xlsx`);
});

document.getElementById('scExportPdf').addEventListener('click', ()=>{
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit:'pt', format:'a4', orientation:'landscape' });
  const today = new Date().toLocaleDateString('pt-BR');
  const k = scCurrentKey();
  const snapshot = scData[k] || {};
  let totalPontos = 0;

  doc.setFont('helvetica','bold'); doc.setFontSize(16); doc.setTextColor(48,79,126);
  doc.text('Scorecard 2026', 40, 40);
  doc.setFont('helvetica','normal'); doc.setFontSize(9); doc.setTextColor(110,110,110);
  doc.text(`Gerado em ${today} · mês: ${MONTH_PT[parseInt(k.split('-')[1])-1]}/${k.split('-')[0]}`, 40, 56);

  const body = SC_INDICATORS.map(ind=>{
    const value = snapshot[ind.key];
    const { pass, pontos, hasValue } = scIndicatorResult(ind, value);
    totalPontos += pontos;
    return [ind.label, ind.peso.toFixed(2)+'%', ind.meta+ind.unit, hasValue? value.toFixed(1)+ind.unit:'—', hasValue? pontos.toFixed(2)+'%':'—', hasValue? (pass?'Dentro da meta':'Fora da meta') : 'Sem dado'];
  });
  body.push(['TOTAL','','','', totalPontos.toFixed(2)+'%', '']);

  doc.autoTable({
    startY: 70,
    head: [['Indicador','Peso','Meta','Resultado','Pontos','Situação']],
    body,
    headStyles:{fillColor:[48,79,126],textColor:255,fontStyle:'bold'},
    styles:{font:'helvetica',fontSize:9,cellPadding:5}, theme:'grid',
    didParseCell:(data)=>{ if(data.section==='body'&&data.column.index===5){ data.cell.styles.textColor = data.cell.raw==='Dentro da meta'?[96,147,70]:(data.cell.raw==='Fora da meta'?[192,57,43]:[150,150,150]); data.cell.styles.fontStyle='bold'; } }
  });

  doc.save(`Scorecard_2026_${k}_${new Date().toISOString().slice(0,10)}.pdf`);
});

/* ---------- Sessão (salvar/carregar tudo em JSON) ---------- */
// Generic deep-walk so we don't have to hand-write serialization for every tab's
// specific shape. Date and Map instances get tagged so they round-trip correctly;
// everything else (plain objects/arrays/numbers/strings) passes through as-is.
function sessionPack(value){
  if(value instanceof Date) return { __type:'Date', iso: value.toISOString() };
  if(value instanceof Map) return { __type:'Map', entries: Array.from(value.entries()).map(([k,v])=>[sessionPack(k), sessionPack(v)]) };
  if(Array.isArray(value)) return value.map(sessionPack);
  if(value && typeof value === 'object'){
    const out = {};
    Object.keys(value).forEach(k=>{ out[k] = sessionPack(value[k]); });
    return out;
  }
  return value;
}
function sessionUnpack(value){
  if(value && typeof value === 'object' && value.__type === 'Date') return new Date(value.iso);
  if(value && typeof value === 'object' && value.__type === 'Map') return new Map(value.entries.map(([k,v])=>[sessionUnpack(k), sessionUnpack(v)]));
  if(Array.isArray(value)) return value.map(sessionUnpack);
  if(value && typeof value === 'object'){
    const out = {};
    Object.keys(value).forEach(k=>{ out[k] = sessionUnpack(value[k]); });
    return out;
  }
  return value;
}

function buildSessionSnapshot(){
  return {
    version: 1,
    savedAt: new Date().toISOString(),
    rdo: { rdoEntries },
    idp: { idpEntries },
    idc: { idcFcstEntries, idcRealEntries, idcMapping },
    rnc: { rncEntries },
    treinamentos: { trnEntries },
    nej: { nejMonthlyEntries, nejMondayEntries, nejEdits, nejMatchOverrides },
    fs: { fsEntries },
    txd: { txdEntries, txdManualRows },
    scorecard: { scData },
  };
}

document.getElementById('sessionSaveBtn').addEventListener('click', ()=>{
  const snapshot = buildSessionSnapshot();
  const packed = sessionPack(snapshot);
  const json = JSON.stringify(packed);
  const blob = new Blob([json], { type:'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `Central_Indicadores_Sessao_${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
  document.getElementById('sessionStatus').textContent = 'Sessão salva.';
});

document.getElementById('sessionLoadBtn').addEventListener('click', ()=> document.getElementById('sessionLoadFile').click());
document.getElementById('sessionLoadFile').addEventListener('change', async (e)=>{
  const file = e.target.files[0];
  e.target.value = '';
  if(!file) return;
  const statusEl = document.getElementById('sessionStatus');
  statusEl.textContent = 'Carregando sessão…';
  try{
    const text = await file.text();
    const packed = JSON.parse(text);
    const snapshot = sessionUnpack(packed);

    // Substitui (não mescla) o estado de cada aba pelo que veio no arquivo.
    rdoEntries = snapshot.rdo.rdoEntries || [];
    idpEntries = snapshot.idp.idpEntries || [];
    idcFcstEntries = snapshot.idc.idcFcstEntries || [];
    idcRealEntries = snapshot.idc.idcRealEntries || [];
    idcMapping = snapshot.idc.idcMapping || {};
    rncEntries = snapshot.rnc.rncEntries || [];
    trnEntries = snapshot.treinamentos.trnEntries || [];
    nejMonthlyEntries = snapshot.nej.nejMonthlyEntries || [];
    nejMondayEntries = snapshot.nej.nejMondayEntries || [];
    nejEdits = snapshot.nej.nejEdits || {};
    nejMatchOverrides = snapshot.nej.nejMatchOverrides || {};
    fsEntries = snapshot.fs.fsEntries || [];
    txdEntries = snapshot.txd.txdEntries || [];
    txdManualRows = snapshot.txd.txdManualRows || [];
    scData = snapshot.scorecard.scData || {};

    // Re-renderiza cada aba a partir do estado restaurado (também atualiza as
    // listas de arquivo/chips na tela).
    renderRdoFileList(); combineAndRenderRdo();
    renderIdpFileList(); combineAndRenderIdp();
    renderIdcFcstFileList(); renderIdcFcstPreview();
    renderIdcRealFileList(); renderIdcRealPreview();
    renderRncFileList(); combineAndRenderRnc();
    renderTrnFileList(); combineAndRenderTrn();
    renderNejMonthlyFileList();
    renderNejMondayFileList();
    combineAndRenderNejMonday(); // must run before NEJ so the auto-match has Monday data ready
    combineAndRenderNej();
    renderFsFileList(); combineAndRenderFs();
    renderTxdFileList(); combineAndRenderTxd();
    renderScorecard();
    renderPainelGeral(); // faltava — o Painel Geral (2026) lê scData direto e precisa recarregar também

    statusEl.textContent = `Sessão de ${snapshot.savedAt ? new Date(snapshot.savedAt).toLocaleString('pt-BR') : '—'} carregada.`;
  }catch(err){
    statusEl.textContent = 'Erro ao carregar sessão: ' + err.message;
  }
});


/* ================= PAINEL (visual novo) ================= */
// Infraestrutura compartilhada por todas as abas: cada aba tem um botão "Publicar"
// que pega o resultado já calculado (xxxLastData) e monta um objeto no formato da
// antiga aba "DETALHES" (chave -> valor), guardado em pnlPublished[chave_indicador].
// O Painel de cada aba, e o Painel Geral (2026), leem só de pnlPublished — nunca
// direto dos xxxLastData — assim o que aparece publicado só muda quando alguém
// aperta "Publicar" de novo, mesmo que os dados brutos daquela aba já tenham mudado.
const PNL_BL='#304F7E', PNL_GO='#EAA239', PNL_GR='#609346', PNL_RD='#CC5121', PNL_GY='#9EA5AE';
const PNL_CH = {};
let pnlPublished = {}; // 'rdo' -> { pontos, peso, meta, resultado, unidades:[{n,v}], mensal:[...], ... }

function setSubtab(panelId, subtab){
  const nav = document.getElementById(panelId+'SubtabNav');
  if(nav) nav.querySelectorAll('button').forEach((b,i)=> b.classList.toggle('active', (i===0)===(subtab==='painel')));
  document.getElementById(panelId+'SubtabPainel').classList.toggle('active', subtab==='painel');
  document.getElementById(panelId+'SubtabAdmin').classList.toggle('active', subtab==='admin');
}

function pnlDot(c){ return '<span class="dot '+c+'"></span>'; }
function pnlBdg(t,c){ return '<span class="badge '+c+'">'+t+'</span>'; }
function pnlMcInfo(lbl,val,sub,c){
  return '<div class="mc '+c+'">'
    +'<div class="ml">'+lbl+'</div>'
    +'<div class="mv '+c+'">'+val+'</div>'
    +'<div class="mm">'+sub+'</div>'
    +'</div>';
}
function pnlMc(lbl,val,meta,c,ok){
  return '<div class="mc '+c+'">'
    +'<div class="ml">'+lbl+'</div>'
    +'<div class="mv '+c+'">'+val+'</div>'
    +'<div class="mm">'+meta+'</div>'
    +'<div class="ms '+(ok?'ok':'no')+'">'+(ok?'&#10003; Atingida':'&#10007; Abaixo')+'</div>'
    +'</div>';
}
function pnlUb(units, meta, inv){
  let h='';
  for(const u of units){
    const pct = inv ? Math.min(100, Math.round(meta/Math.max(u.v,0.01)*100)) : Math.min(100, u.v);
    const cc = inv ? (u.v<=meta?PNL_GR:PNL_RD) : (u.v>=meta?PNL_GR:PNL_RD);
    h += '<div class="urow">'
      +'<div class="uname">'+u.n+'</div>'
      +'<div class="utrack"><div class="ufill" style="width:'+pct+'%;background:'+cc+'"></div></div>'
      +'<div class="uval" style="color:'+cc+'">'+(inv? u.v+'d' : u.v+'%')+'</div>'
      +'</div>';
  }
  return h;
}
function pnlDestroyChart(id){
  const el = document.getElementById(id);
  if(!el) return;
  try{ const ex = Chart.getChart(el); if(ex) ex.destroy(); }catch(e){}
  try{ if(PNL_CH[id]) PNL_CH[id].destroy(); }catch(e){}
}
function pnlLine(id, labels, datasets, yFmt){
  pnlDestroyChart(id);
  const el = document.getElementById(id); if(!el) return;
  PNL_CH[id] = new Chart(el, { type:'line', data:{ labels, datasets },
    options:{ responsive:true, maintainAspectRatio:false, spanGaps:false,
      plugins:{ legend:{ display:true, position:'bottom', labels:{ font:{family:'Montserrat',size:10}, boxWidth:10, padding:8 } } },
      scales:{ x:{ grid:{display:false}, ticks:{font:{family:'Montserrat',size:10}} },
                y:{ grid:{color:'#f4f4f4'}, ticks:{ font:{family:'Montserrat',size:10}, callback: yFmt? (v=>v+yFmt) : undefined } } } } });
}
function pnlPie(id, labels, data, colors){
  pnlDestroyChart(id);
  const el = document.getElementById(id); if(!el) return;
  const shortLabels = labels.map(l=> l.length > 28 ? l.slice(0,26)+'…' : l);
  PNL_CH[id] = new Chart(el, { type:'doughnut', data:{ labels: shortLabels, datasets:[{ data, backgroundColor:colors, borderWidth:2 }] },
    options:{ responsive:true, maintainAspectRatio:false,
      plugins:{ legend:{ position:'bottom', labels:{ font:{family:'Montserrat',size:9.5}, boxWidth:10, padding:8 } },
        tooltip:{ callbacks:{ title: (items)=> labels[items[0].dataIndex] } } } } });
}

/* ---- RDO: publicar + renderizar painel ---- */
document.getElementById('rdoPublishBtn').addEventListener('click', ()=>{
  if(!rdoLastData){ alert('Carregue e calcule os dados de RDO antes de publicar.'); return; }
  const d = rdoLastData;
  pnlPublished.rdo = {
    pontos: 1800, peso: 0.15, meta: 76,
    resultado: d.totalEmitidos ? d.totalAprovados/d.totalEmitidos*100 : 0,
    aprovados: d.totalAprovados, emitidos: d.totalEmitidos,
    emRevisaoPct: d.totalEmitidos ? d.totalRevisar/d.totalEmitidos*100 : 0,
    preenchendoPct: d.totalEmitidos ? d.totalPreenchendo/d.totalEmitidos*100 : 0,
    unidades: d.units.map(u=>({ n:u.name.replace(/^INPASA\s*/i,'').trim(), v:Math.round(u.aderencia*100) })).sort((a,b)=>b.v-a.v),
    mensal: d.months.map(m=>({ label:m.label, v: m.emitidos? Math.round(m.aprovados/m.emitidos*100) : 0 })),
    publishedAt: new Date().toLocaleString('pt-BR'),
  };
  document.getElementById('rdoPublishStatus').textContent = 'Publicado em ' + pnlPublished.rdo.publishedAt;
  renderRdoPainel();
  renderPainelGeral();
});

function renderRdoPainel(){
  const d = pnlPublished.rdo;
  const empty = document.getElementById('rdoPainelEmpty');
  const content = document.getElementById('rdoPainelContent');
  if(!d){ empty.style.display='block'; content.innerHTML=''; return; }
  empty.style.display = 'none';

  const rdo = Math.round(d.resultado);
  const rdoOk = rdo >= d.meta;
  const emRevisaoQtd = Math.round(d.emRevisaoPct/100 * d.emitidos);
  const preenchendoQtd = Math.round(d.preenchendoPct/100 * d.emitidos);

  let h = '<div class="ph">Aprovação de RDO</div>';
  h += '<div class="ps" style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">'
     + '<span style="background:'+PNL_BL+';color:#fff;font-weight:800;font-size:13px;padding:5px 12px;border-radius:20px;">META: >'+d.meta+'%</span>'
     + 'Resultado: <strong style="color:'+(rdoOk?PNL_GR:PNL_RD)+';font-size:14px;">'+rdo+'%</strong>'
     + '<span style="color:#bbb;">— publicado em '+d.publishedAt+'</span></div>';
  h += '<div class="mgrid">';
  h += pnlMc('Resultado', rdo+'%', 'Meta >'+d.meta+'%', rdoOk?'G':'R', rdoOk);
  h += pnlMcInfo('Relatórios aprovados', d.aprovados.toLocaleString('pt-BR'), 'De '+d.emitidos.toLocaleString('pt-BR')+' emitidos', 'G');
  h += pnlMcInfo('Em revisão', d.emRevisaoPct.toFixed(1)+'%', emRevisaoQtd.toLocaleString('pt-BR')+' relatórios', 'A');
  h += pnlMcInfo('Preenchendo', d.preenchendoPct.toFixed(1)+'%', preenchendoQtd.toLocaleString('pt-BR')+' relatórios', 'A');
  h += '</div>';
  h += '<div class="g2"><div class="card"><div class="ct">Aprovação mensal</div><div class="cw" style="height:220px"><canvas id="cRdoPainel"></canvas></div></div>';
  h += '<div class="card"><div class="ct">Aprovação por unidade</div>'+pnlUb(d.unidades, d.meta, false)+'</div></div>';
  content.innerHTML = h;

  setTimeout(()=>{
    pnlLine('cRdoPainel', d.mensal.map(m=>m.label), [
      { label:'Aprovação (%)', data:d.mensal.map(m=>m.v), borderColor:PNL_BL, backgroundColor:PNL_BL+'22', tension:.3, fill:true, pointBackgroundColor:PNL_BL, pointRadius:5, borderWidth:2 },
      { label:'Meta ('+d.meta+'%)', data:d.mensal.map(()=>d.meta), borderColor:PNL_GO, borderDash:[5,4], pointRadius:0, borderWidth:2 },
    ], '%');
  }, 60);
}

/* ---- Painel Geral (2026) ---- */
const PNL_INDICATOR_DEFS = [
  { key:'rdo', label:'Aprovação RDO', peso:15.00 },
  { key:'cronograma', label:'Aderência Cronograma', peso:15.60 },
  { key:'idc', label:'Índice Desemp. Custo', peso:8.63 },
  { key:'rnc', label:'RNC', peso:5.75 },
  { key:'treinamentos', label:'Treinamentos', peso:15.00 },
  { key:'nej', label:'NEJ', peso:6.57 },
  { key:'taxa_desligamento', label:'Taxa Desligamento', peso:7.70 },
  { key:'5s', label:'5S', peso:13.66 },
  { key:'taxa_acidentes', label:'Taxa de Acidentes', peso:12.09 },
];

const PNL_SHORT_LABELS = { rdo:'RDO', cronograma:'Cronograma', idc:'IDC', rnc:'RNC', treinamentos:'Treino', nej:'NEJ', taxa_desligamento:'Desligto.', '5s':'5S', taxa_acidentes:'Acidentes' };
const PNL_META_MAP = { rdo:76, cronograma:98, idc:80, rnc:15, treinamentos:90, nej:80, taxa_desligamento:2, '5s':95, taxa_acidentes:7.5 };
const PNL_LOWER_BETTER = { rnc:true, taxa_desligamento:true, taxa_acidentes:true };

// Cada indicador tem uma unidade diferente (%, dias, pontos) — pra caber os 9 num só
// gráfico, normalizamos tudo como "% da meta atingida" em vez do valor bruto.
// Indicadores "quanto menor melhor" invertem a conta (meta/resultado), então bater
// exatamente na meta sempre vira ~100% nos dois casos.
function pnlPctOfMeta(key, resultado){
  if(resultado===null || resultado===undefined || isNaN(resultado)) return null;
  const meta = PNL_META_MAP[key];
  if(PNL_LOWER_BETTER[key]) return resultado>0 ? (meta/resultado*100) : 100;
  if(key==='idc') return resultado; // já é uma % de aderência ao orçado, sem inverter
  return resultado/meta*100;
}

function renderPainelGeral(){
  const empty = document.getElementById('pgPainelEmpty');
  const content = document.getElementById('pgPainelContent');
  const publishedKeys = Object.keys(pnlPublished);
  const hasScData = (typeof scData!=='undefined') && Object.keys(scData).length > 0;
  if(!publishedKeys.length && !hasScData){ empty.style.display='block'; content.innerHTML=''; return; }
  empty.style.display = 'none';

  // usa o resultado publicado quando existir; senão cai pro que já foi puxado pro
  // scorecard (scData) na Administração; senão fica sem dado (semáforo cinza).
  const scKey = scCurrentKey ? scCurrentKey() : null;
  const scSnapshot = (scKey && typeof scData!=='undefined' && scData[scKey]) || {};
  const ind = PNL_INDICATOR_DEFS.map(def=>{
    const pub = pnlPublished[def.key];
    const resultado = pub ? pub.resultado : (scSnapshot[def.key]!==undefined ? scSnapshot[def.key] : null);
    return { ...def, resultado, hasData: resultado!==null && resultado!==undefined, pub };
  });

  function passes(def){
    if(!def.hasData) return null;
    const meta = PNL_META_MAP[def.key];
    if(def.key==='idc') return def.resultado>=80 && def.resultado<=120;
    return PNL_LOWER_BETTER[def.key] ? def.resultado <= meta : def.resultado >= meta;
  }

  const monthKeysWithData = (typeof scData!=='undefined') ? Object.keys(scData).sort() : [];

  // 1.930,33 = 11.582 ÷ 6 — a fatia mensal do pool de pontos do semestre (confirmado nas
  // fórmulas da planilha original: E5=$L$24/6, L24=11582 fixo). Cada indicador, em cada
  // mês carregado, ganha peso×1.930,33 se bateu a meta NAQUELE mês — soma real mês a mês,
  // não só o mês mais recente.
  const PNL_MONTHLY_POOL = 1930.333333333333;
  const pontuacaoPrevista = monthKeysWithData.length * PNL_MONTHLY_POOL;
  let pontosRealizados = 0;
  monthKeysWithData.forEach(mk=>{
    const snap = scData[mk] || {};
    PNL_INDICATOR_DEFS.forEach(def=>{
      const v = snap[def.key];
      if(v===undefined || v===null) return;
      const meta = PNL_META_MAP[def.key];
      const pass = def.key==='idc' ? (v>=80&&v<=120) : (PNL_LOWER_BETTER[def.key] ? v<=meta : v>=meta);
      if(pass) pontosRealizados += (def.peso/100) * PNL_MONTHLY_POOL;
    });
  });
  pontosRealizados = Math.round(pontosRealizados);
  const atendimentoGeral = pontuacaoPrevista ? (pontosRealizados/pontuacaoPrevista*100) : 0;
  const dataReferencia = new Date().toLocaleDateString('pt-BR');

  let h = '<div class="mgrid">';
  h += pnlMcInfo('Pontuação Prevista', pontuacaoPrevista.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}), monthKeysWithData.length+' mês(es) carregado(s)', '');
  h += pnlMcInfo('Pontos Realizados', pontosRealizados.toLocaleString('pt-BR'), 'Execução acumulada do painel', 'A');
  h += pnlMcInfo('Atendimento Geral', atendimentoGeral.toFixed(0)+'%', 'Percentual consolidado do PPR', atendimentoGeral>=95?'G':(atendimentoGeral>=70?'A':'R'));
  h += pnlMcInfo('Status de Referência', dataReferencia, 'Data base do painel', '');
  h += '</div>';

  // Resumo Executivo — farol mensal (Meta/Peso + um ponto por mês) e as legendas de leitura
  h += '<div class="subtitle-block" style="margin:18px 0 8px;"><h3 style="color:'+PNL_BL+';">Resumo Executivo</h3></div>';
  h += '<div class="card"><div class="ct">Resultado geral do PPR Obras</div><p class="ps" style="margin:-6px 0 12px;">Leitura consolidada dos indicadores e pesos mensais.</p>';
  h += '<div style="overflow-x:auto"><table class="dt" style="min-width:700px"><thead><tr><th>Entrega</th><th>Meta</th><th>Peso</th>';
  monthKeysWithData.forEach(mk=>{ h += '<th style="text-align:center">'+MONTH_PT[parseInt(mk.split('-')[1])-1].slice(0,3)+'</th>'; });
  h += '<th>Parcial</th><th>Consolidado</th></tr></thead><tbody>';
  ind.forEach(def=>{
    const metaTxt = (PNL_LOWER_BETTER[def.key]?'<':'>') + PNL_META_MAP[def.key] + (def.key==='rnc'?' dias':(def.key==='5s'?'':'%'));
    h += '<tr><td>'+def.label.toUpperCase()+'</td><td>'+metaTxt+'</td><td>'+def.peso.toFixed(2)+'%</td>';
    const vals = [];
    monthKeysWithData.forEach(mk=>{
      const v = (scData[mk]||{})[def.key];
      if(v===undefined || v===null){ h += '<td style="text-align:center">'+pnlDot('X')+'</td>'; return; }
      vals.push(v);
      const ok = def.key==='idc' ? (v>=80&&v<=120) : (PNL_LOWER_BETTER[def.key] ? v<=PNL_META_MAP[def.key] : v>=PNL_META_MAP[def.key]);
      h += '<td style="text-align:center">'+pnlDot(ok?'G':'R')+'</td>';
    });
    const parcial = vals.length ? (vals.reduce((s,v)=>s+v,0)/vals.length) : (def.hasData?def.resultado:null);
    const parcialOk = parcial!==null ? (def.key==='idc' ? (parcial>=80&&parcial<=120) : (PNL_LOWER_BETTER[def.key] ? parcial<=PNL_META_MAP[def.key] : parcial>=PNL_META_MAP[def.key])) : null;
    h += '<td>'+(parcial!==null?parcial.toFixed(1)+(def.key==='rnc'?' dias':(def.key==='5s'?'':'%')):'—')+'</td>';
    h += '<td>'+(parcialOk===null?'—':pnlBdg(parcialOk?'OK':'Atenção', parcialOk?'G':'R'))+'</td></tr>';
  });
  h += '</tbody></table></div></div>';

  h += '<div class="g2">';
  h += '<div class="card"><div class="ct">Legenda · Indicadores gerais</div><p class="ps" style="margin:-6px 0 10px;">Faixas de leitura para os indicadores gerais.</p>'
     + '<div style="display:flex;align-items:center;gap:10px;padding:8px 0;">'+pnlDot('G')+' <div><strong>≥ 95%</strong><br><span style="color:#999;font-size:11px;">Valor atendido</span></div></div>'
     + '<div style="display:flex;align-items:center;gap:10px;padding:8px 0;">'+pnlDot('A')+' <div><strong>70% a 79,99%</strong><br><span style="color:#999;font-size:11px;">Atenção</span></div></div>'
     + '<div style="display:flex;align-items:center;gap:10px;padding:8px 0;">'+pnlDot('R')+' <div><strong>&lt; 70%</strong><br><span style="color:#999;font-size:11px;">Fora da meta</span></div></div>'
     + '</div>';
  h += '<div class="card"><div class="ct">Legenda · Indicadores setoriais</div><p class="ps" style="margin:-6px 0 10px;">Faixas de leitura para os indicadores setoriais (por unidade).</p>'
     + '<div style="display:flex;align-items:center;gap:10px;padding:6px 0;">'+pnlDot('G')+' <strong>≥ 95%</strong></div>'
     + '<div style="display:flex;align-items:center;gap:10px;padding:6px 0;"><span class="dot" style="background:#0B7C7A"></span> <strong>90% a 94,99%</strong></div>'
     + '<div style="display:flex;align-items:center;gap:10px;padding:6px 0;"><span class="dot" style="background:#007CC5"></span> <strong>80% a 89,99%</strong></div>'
     + '<div style="display:flex;align-items:center;gap:10px;padding:6px 0;">'+pnlDot('A')+' <strong>70% a 79,99%</strong></div>'
     + '<div style="display:flex;align-items:center;gap:10px;padding:6px 0;">'+pnlDot('R')+' <strong>&lt; 70%</strong></div>'
     + '</div>';
  h += '</div>';

  h += '<div class="g2"><div class="card"><div class="ct">Status por indicador</div><table class="dt"><thead><tr><th>Indicador</th><th>Meta</th><th>Resultado</th><th>Peso</th><th></th></tr></thead><tbody>';
  ind.forEach(def=>{
    const p = passes(def);
    const metaTxt = (PNL_LOWER_BETTER[def.key]?'≤':'>=') + PNL_META_MAP[def.key] + (def.key==='rnc'?'d':(def.key==='5s'?' pts':'%'));
    const valTxt = def.hasData ? def.resultado.toFixed(1)+(def.key==='rnc'?'d':'%') : '—';
    h += '<tr><td>'+def.label+'</td><td>'+metaTxt+'</td><td>'+valTxt+'</td><td>'+def.peso.toFixed(2)+'%</td><td>'+(p===null?pnlDot('X'):pnlDot(p?'G':'R'))+'</td></tr>';
  });
  h += '</tbody></table></div>';

  h += '<div class="card"><div class="ct">Desempenho mensal (% da meta atingida)</div><div class="cw" style="height:260px"><canvas id="cPgMensal"></canvas></div></div></div>';

  content.innerHTML = h;

  // gráfico "Desempenho mensal" — um dataset por mês, os 9 indicadores lado a lado,
  // todos normalizados como % da meta atingida (ver pnlPctOfMeta)
  setTimeout(()=>{
    pnlDestroyChart('cPgMensal');
    const el = document.getElementById('cPgMensal');
    if(!el) return;
    const cores = [PNL_BL,PNL_GO,PNL_GR,'#7B5EA7','#E07B39','#2E8B57'];
    const datasets = monthKeysWithData.map((mk,i)=>({
      label: MONTH_PT[parseInt(mk.split('-')[1])-1]+'/'+mk.split('-')[0].slice(2),
      data: PNL_INDICATOR_DEFS.map(def=> pnlPctOfMeta(def.key, (scData[mk]||{})[def.key])),
      backgroundColor: cores[i%cores.length]+'cc',
    }));
    PNL_CH['cPgMensal'] = new Chart(el, { type:'bar',
      data: { labels: PNL_INDICATOR_DEFS.map(def=>PNL_SHORT_LABELS[def.key]), datasets },
      options: { responsive:true, maintainAspectRatio:false,
        plugins:{ legend:{ display:true, position:'bottom', labels:{font:{family:'Montserrat',size:10},boxWidth:10,padding:8} } },
        scales:{ x:{grid:{display:false},ticks:{font:{family:'Montserrat',size:9}}},
                 y:{grid:{color:'#f4f4f4'},ticks:{font:{family:'Montserrat',size:10},callback:v=>v+'%'}} } } });
  }, 90);
}/* ---- Cronograma (IDP-Disciplinas): publicar + renderizar painel ---- */
document.getElementById('idpPublishBtn').addEventListener('click', ()=>{
  if(!idpLastData){ alert('Carregue e calcule os dados de Cronograma antes de publicar.'); return; }
  const d = idpLastData;

  // agrega Custo Linha de Base / Custo Real por mês, somando todas as unidades e
  // disciplinas — vira a série do gráfico "Aderência mensal" do Painel.
  const byMonth = new Map();
  d.byUnitDetail.forEach(discMap=>{
    discMap.forEach(monthMap=>{
      monthMap.forEach((v,mi)=>{
        if(!byMonth.has(mi)) byMonth.set(mi, {lb:0, real:0});
        const acc = byMonth.get(mi); acc.lb += v.lb; acc.real += v.real;
      });
    });
  });
  const mensal = Array.from(byMonth.entries()).sort((a,b)=>a[0]-b[0]).map(([mi,v])=>({
    label: MONTH_PT[mi]+'/'+d.selectedYear, v: v.lb ? Math.round(v.real/v.lb*100) : 0,
  }));

  pnlPublished.cronograma = {
    pontos: 2100, peso: 0.156, meta: 98,
    resultado: d.aderGeral*100,
    civil: Math.round(d.civilAgg.ad*100), mecanica: Math.round(d.mecanicaAgg.ad*100), eia: Math.round(d.eiaAgg.ad*100),
    unidades: d.unitRows.map(([name,u])=>({ n:name.replace(/^INPASA\s*/i,'').trim(), v: u.lb? Math.round(u.real/u.lb*100) : 0 })).sort((a,b)=>b.v-a.v),
    mensal,
    publishedAt: new Date().toLocaleString('pt-BR'),
  };
  document.getElementById('idpPublishStatus').textContent = 'Publicado em ' + pnlPublished.cronograma.publishedAt;
  renderCronPainel();
  renderPainelGeral();
});

function renderCronPainel(){
  const d = pnlPublished.cronograma;
  const empty = document.getElementById('cronPainelEmpty');
  const content = document.getElementById('cronPainelContent');
  if(!d){ empty.style.display='block'; content.innerHTML=''; return; }
  empty.style.display = 'none';

  const cron = Math.round(d.resultado);
  const cronOk = cron >= d.meta;

  let h = '<div class="ph">Aderência do Cronograma</div>';
  h += '<div class="ps" style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">'
     + '<span style="background:'+PNL_BL+';color:#fff;font-weight:800;font-size:13px;padding:5px 12px;border-radius:20px;">META: >'+d.meta+'%</span>'
     + 'Resultado: <strong style="color:'+(cronOk?PNL_GR:PNL_RD)+';font-size:14px;">'+cron+'%</strong>'
     + '<span style="color:#bbb;">— publicado em '+d.publishedAt+'</span></div>';
  h += '<div class="mgrid">';
  h += pnlMc('Semestral', cron+'%', 'Meta >'+d.meta+'%', cronOk?'G':'R', cronOk);
  h += pnlMc('Civil', d.civil+'%', 'Por disciplina', d.civil>=d.meta?'G':'A', d.civil>=d.meta);
  h += pnlMc('Mecânica', d.mecanica+'%', 'Por disciplina', d.mecanica>=d.meta?'G':'A', d.mecanica>=d.meta);
  h += pnlMc('EIA', d.eia+'%', 'Elétrica+Instrum.+Automação', d.eia>=d.meta?'G':'A', d.eia>=d.meta);
  h += '</div>';
  h += '<div class="g2"><div class="card"><div class="ct">Aderência mensal (%)</div><div class="cw" style="height:220px"><canvas id="cCronPainel"></canvas></div></div>';
  h += '<div class="card"><div class="ct">Aderência por unidade</div>'+pnlUb(d.unidades, d.meta, false)+'</div></div>';
  content.innerHTML = h;

  setTimeout(()=>{
    pnlLine('cCronPainel', d.mensal.map(m=>m.label), [
      { label:'Aderência (%)', data:d.mensal.map(m=>m.v), borderColor:PNL_BL, backgroundColor:PNL_BL+'22', tension:.3, fill:true, pointBackgroundColor:PNL_BL, pointRadius:5, borderWidth:2 },
      { label:'Meta ('+d.meta+'%)', data:d.mensal.map(()=>d.meta), borderColor:PNL_RD, borderDash:[5,4], pointRadius:0, borderWidth:2 },
    ], '%');
  }, 60);
}/* ---- IDC - Custos: publicar + renderizar painel ---- */
document.getElementById('idcPublishBtn').addEventListener('click', ()=>{
  if(!idcLastData || !idcLastData.rows.length){ alert('Carregue e calcule os dados de IDC antes de publicar.'); return; }
  const d = idcLastData;

  // agrega Previsto/Real mensal de todas as unidades, por mês, pro gráfico de linha —
  // usa a série completa (não só o último mês) que cada unidade guarda desde junho.
  const byMonth = new Map();
  d.rows.forEach(r=>{
    (r.series||[]).forEach(mp=>{
      const key = mp.year+'-'+String(mp.monthIndex+1).padStart(2,'0');
      if(!byMonth.has(key)) byMonth.set(key, {previsto:0, real:0, year:mp.year, monthIndex:mp.monthIndex});
      const acc = byMonth.get(key); acc.previsto += mp.previstoMensal; acc.real += mp.realMensal;
    });
  });
  const mensal = Array.from(byMonth.values()).sort((a,b)=>(a.year-b.year)||(a.monthIndex-b.monthIndex)).map(v=>({
    label: MONTH_PT[v.monthIndex]+'/'+v.year, v: v.previsto ? Math.round(v.real/v.previsto*100) : 0,
  }));

  pnlPublished.idc = {
    pontos: 1209, peso: 0.0863, metaMin: 80, metaMax: 120,
    resultado: d.adGeral*100,
    orcado: d.totalPrevisto, realizado: d.totalReal,
    unidades: d.rows.map(r=>({ n:r.unit.replace(/^INPASA\s*/i,'').trim(), mensal:Math.round(r.adMensal*100), acumulado:Math.round(r.adAc*100) })).sort((a,b)=>b.acumulado-a.acumulado),
    mensal,
    publishedAt: new Date().toLocaleString('pt-BR'),
  };
  document.getElementById('idcPublishStatus').textContent = 'Publicado em ' + pnlPublished.idc.publishedAt;
  renderIdcPainel();
  renderPainelGeral();
});

function pnlFmtMoney(v){
  if(v===null||v===undefined||isNaN(v)) return '—';
  const abs = Math.abs(v);
  if(abs >= 1e9) return 'R$ '+(v/1e9).toFixed(2).replace('.',',')+'Bi';
  if(abs >= 1e6) return 'R$ '+(v/1e6).toFixed(1).replace('.',',')+' milhões';
  return fmtCurrency(v);
}

function renderIdcPainel(){
  const d = pnlPublished.idc;
  const empty = document.getElementById('idcPainelEmpty');
  const content = document.getElementById('idcPainelContent');
  if(!d){ empty.style.display='block'; content.innerHTML=''; return; }
  empty.style.display = 'none';

  const idc = Math.round(d.resultado);
  const idcOk = idc >= d.metaMin && idc <= d.metaMax;

  let h = '<div class="ph">Índice de Desempenho de Custo</div>';
  h += '<div class="ps" style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">'
     + '<span style="background:'+PNL_BL+';color:#fff;font-weight:800;font-size:13px;padding:5px 12px;border-radius:20px;">META: '+d.metaMin+'% – '+d.metaMax+'%</span>'
     + 'Resultado: <strong style="color:'+(idcOk?PNL_GR:PNL_RD)+';font-size:14px;">'+idc+'%</strong>'
     + '<span style="color:#bbb;">— publicado em '+d.publishedAt+'</span></div>';
  h += '<div class="mgrid">';
  h += pnlMc('IDC Semestral', idc+'%', 'Meta '+d.metaMin+'-'+d.metaMax+'%', idcOk?'G':'R', idcOk);
  h += pnlMcInfo('Previsto acumulado', pnlFmtMoney(d.orcado), 'Desde junho/26', 'G');
  h += pnlMcInfo('Real acumulado', pnlFmtMoney(d.realizado), 'Desde junho/26', d.realizado<=d.orcado?'G':'A');
  h += '</div>';
  h += '<div class="g2"><div class="card"><div class="ct">Aderência do orçamento (%) — por mês</div><div class="cw" style="height:220px"><canvas id="cIdcPainel"></canvas></div></div>';
  h += '<div class="card"><div class="ct">Aderência acumulada por unidade</div>'+pnlUb(d.unidades.map(u=>({n:u.n,v:u.acumulado})), d.metaMin, false)+'</div></div>';
  content.innerHTML = h;

  setTimeout(()=>{
    pnlLine('cIdcPainel', d.mensal.map(m=>m.label), [
      { label:'Aderência (%)', data: d.mensal.map(m=>m.v), borderColor:PNL_BL, tension:.3, fill:false, pointBackgroundColor:PNL_BL, pointRadius:5, borderWidth:2 },
      { label:'Lim. inf. ('+d.metaMin+'%)', data: d.mensal.map(()=>d.metaMin), borderColor:PNL_GO, borderDash:[4,3], pointRadius:0 },
      { label:'Lim. sup. ('+d.metaMax+'%)', data: d.mensal.map(()=>d.metaMax), borderColor:PNL_GO, borderDash:[4,3], pointRadius:0 },
    ], '%');
  }, 60);
}/* ---- RNC: publicar + renderizar painel ---- */
document.getElementById('rncPublishBtn').addEventListener('click', ()=>{
  if(!rncLastData){ alert('Carregue e calcule os dados de RNC antes de publicar.'); return; }
  const d = rncLastData;
  // média ponderada dos dias de resolução ao longo dos meses carregados, usando
  // "solucionados" como peso (meses sem RNC tratada não entram na média)
  const withDias = d.monthKeys.filter(m=>m.dias!==null && m.dias!==undefined);
  const totalSolucionados = withDias.reduce((s,m)=>s+m.solucionados,0);
  const resultado = totalSolucionados ? withDias.reduce((s,m)=>s+m.dias*m.solucionados,0)/totalSolucionados : (withDias.length? withDias.reduce((s,m)=>s+m.dias,0)/withDias.length : 0);

  const top = d.ofensores.slice(0,4);
  const outrosPct = 1 - top.reduce((s,o)=>s+o.pct,0);

  pnlPublished.rnc = {
    pontos: 690, peso: 0.0575, meta: 15,
    resultado,
    semestreResolvidas: d.totalTratadas, semestreTotal: d.totalCriadas,
    unidades: d.units.map(u=>({ n:u.name.replace(/^INPASA\s*/i,'').trim(), v:Math.round(u.ad*100) })).sort((a,b)=>b.v-a.v),
    mensal: d.monthKeys.map(m=>({ label:m.label, v: m.dias!==null? Math.round(m.dias*10)/10 : null })),
    ofensores: [...top.map(o=>({n:o.name, pct:Math.round(o.pct*1000)/10})), ...(outrosPct>0.001?[{n:'Outros', pct:Math.round(outrosPct*1000)/10}]:[])],
    publishedAt: new Date().toLocaleString('pt-BR'),
  };
  document.getElementById('rncPublishStatus').textContent = 'Publicado em ' + pnlPublished.rnc.publishedAt;
  renderRncPainel();
  renderPainelGeral();
});

function renderRncPainel(){
  const d = pnlPublished.rnc;
  const empty = document.getElementById('rncPainelEmpty');
  const content = document.getElementById('rncPainelContent');
  if(!d){ empty.style.display='block'; content.innerHTML=''; return; }
  empty.style.display = 'none';

  const rnc = Math.round(d.resultado*10)/10;
  const rncOk = rnc <= d.meta;
  const semestrePct = d.semestreTotal ? Math.round(d.semestreResolvidas/d.semestreTotal*100) : 0;

  let h = '<div class="ph">RNC — lução</div>';
  h += '<div class="ps" style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">'
     + '<span style="background:'+PNL_BL+';color:#fff;font-weight:800;font-size:13px;padding:5px 12px;border-radius:20px;">META: ≤'+d.meta+' dias</span>'
     + 'Resultado: <strong style="color:'+(rncOk?PNL_GR:PNL_RD)+';font-size:14px;">'+rnc+' dias</strong>'
     + '<span style="color:#bbb;">— quanto menor, melhor — publicado em '+d.publishedAt+'</span></div>';
  h += '<div class="mgrid">';
  h += pnlMc('Resultado', rnc+' dias', 'Meta ≤'+d.meta+' dias', rncOk?'G':'R', rncOk);
  h += pnlMcInfo('Semestre', semestrePct+'%', d.semestreResolvidas+'/'+d.semestreTotal+' resolvidas', 'G');
  h += '</div>';
  h += '<div class="g2"><div class="card"><div class="ct">Tempo médio por mês (dias)</div><div class="cw" style="height:220px"><canvas id="cRncPainel"></canvas></div></div>';
  h += '<div class="card"><div class="ct">Origem das não conformidades</div><div class="cw" style="height:260px"><canvas id="cRncPie"></canvas></div></div></div>';
  h += '<div class="card"><div class="ct">Aderência de tratativa por unidade</div>'+pnlUb(d.unidades, 80, false)+'</div>';
  content.innerHTML = h;

  setTimeout(()=>{
    pnlLine('cRncPainel', d.mensal.map(m=>m.label), [
      { label:'Tempo médio (dias)', data:d.mensal.map(m=>m.v), borderColor:PNL_BL, tension:.3, fill:false, pointBackgroundColor:PNL_BL, pointRadius:5, borderWidth:2, spanGaps:true },
      { label:'Meta ('+d.meta+' dias)', data:d.mensal.map(()=>d.meta), borderColor:PNL_GO, borderDash:[5,4], pointRadius:0 },
    ], 'd');
    pnlPie('cRncPie', d.ofensores.map(o=>o.n+' ('+o.pct+'%)'), d.ofensores.map(o=>o.pct), [PNL_BL,PNL_GO,PNL_GR,PNL_GY,'#7B5EA7']);
  }, 60);
}/* ---- Treinamentos: publicar + renderizar painel ---- */
